)

// realmAddr is the address coins land on when someone calls this realm.
var realmAddr = chain.PackageAddress("gno.land/r/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif")

const gnot = int64(1000000)

// reset clears the realm state between tests: every test runs in the same
// package instance.
func reset() {
	circles = nil
	seq = 0
}

// payFrom simulates the coins a transaction carries: they exist on the realm
// account and they are reported as the origin send of the current call.
//
// Note: testing.SetRealm does NOT survive a function boundary, so callers must
// set the realm inline in the same frame that makes the crossing call.
func payFrom(amount int64) {
	coins := chain.NewCoins(chain.NewCoin("ugnot", amount))
	testing.IssueCoins(realmAddr, coins)
	testing.SetOriginSend(coins)
}

func balanceOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, "ugnot")
}

func fund(addr address, amount int64) {
	testing.IssueCoins(addr, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

package kolektif

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif/rosca"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/sys/users"
)

// pkgPath is this realm's own path, used to build action links.
const pkgPath = "gno.land/r/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif"

// Render is the gnoweb view of the realm. Every page is Markdown that gnoweb
// renders directly, so the app ships with no frontend at all: the "UI" is
// computed from chain state, and every button is a link that prepares a
// transaction for the visitor's wallet.
func Render(path string) string {
	p := strings.Trim(path, "/")
	switch {
	case p == "":
		return renderIndex()
	case p == "about":
		return renderAbout()
	case strings.HasPrefix(p, "circle/"):
		return renderCirclePath(strings.TrimPrefix(p, "circle/"))
	case strings.HasPrefix(p, "member/"):
		return renderMember(address(strings.TrimPrefix(p, "member/")))
	}
	return notFound(p)
}

// --- pages -------------------------------------------------------------

func renderIndex() string {
	count, active, escrowed, paidOut := GlobalStats()

	out := "# Kolektif\n\n"
	out += "**Rotating savings circles, on chain.** Gno.land's first ROSCA: a group locks "
	out += "the same contribution every round, one member takes the whole pot each round, "
	out += "and the payout order is fixed by chain state so nobody can rig it.\n\n"
	out += "> Three neighbours, 1 GNOT per round, three rounds: everyone pays 3 GNOT, everyone "
	out += "takes 3 GNOT home once, nobody needs a bank. Collateral makes skipping a round expensive.\n\n"

	out += ufmt.Sprintf("**%d circles** · **%d running** · **%s escrowed** · **%s paid out**\n\n",
		count, active, money(escrowed), money(paidOut))

	out += "## Take a seat\n\n"
	out += "- **Open a circle** — [transaction](" + helpLink("Create") + ") · arguments: name, contribution in ugnot, seats (3-50), round length in seconds\n"
	out += "- **Join an open circle** — [transaction](" + helpLink("Join") + ") · argument: id · locks exactly one contribution as collateral\n"
	out += "- **Pay a round** — [transaction](" + helpLink("Contribute") + ") · argument: id · releases the pot when the last member pays\n"
	out += "- **Settle a stalled round** — [transaction](" + helpLink("Advance") + ") · argument: id · only after the deadline, anyone may call it\n"
	out += "- **[How it works](" + pkgPath + ":about)** — collateral, defaults, payout order, and why it always balances\n\n"

	out += "---\n\n## Circles\n\n"
	if len(circles) == 0 {
		out += "_No circle yet. Open the first one._\n\n"
		out += "```sh\n" + createCLI() + "\n```\n"
		return out
	}
	for i := len(circles) - 1; i >= 0; i-- {
		out += renderCircleCard(circles[i])
	}
	return out
}

// renderCircleCard is one entry in the index list: enough state to decide
// whether the circle is worth a click.
func renderCircleCard(c *Circle) string {
	settled, planned := c.Progress()
	out := "### #" + strconv.FormatUint(c.ID, 10) + " · " + c.Name + " · `" + c.Status.String() + "`\n\n"
	out += ufmt.Sprintf("%s per round · %d seats · rounds last %s · full pot %s\n\n",
		money(c.Params.Contribution), c.Params.Size, rosca.HumanDuration(c.Params.RoundSpan), money(c.Params.Pot()))
	if c.Status == rosca.StatusOpen {
		out += ufmt.Sprintf("Seats %s %d/%d · waiting for members\n\n",
			rosca.Bar(c.Seats(), c.Params.Size, 14), c.Seats(), c.Params.Size)
	} else if c.Status == rosca.StatusActive {
		next := "nobody left"
		bi := c.NextBeneficiary()
		if bi >= 0 {
			next = who(c.Members[bi].Addr)
		}
		out += ufmt.Sprintf("Payouts %s %d/%d · next pot to %s\n\n",
			rosca.Bar(settled, planned, 14), settled, planned, next)
	} else {
		out += ufmt.Sprintf("Closed %s · %s paid out in total\n\n",
			c.ClosedAt.Format("02 Jan 2006"), money(c.PaidOutTotal))
	}
	out += "[Enter circle](" + pkgPath + ":circle/" + strconv.FormatUint(c.ID, 10) + ")\n\n---\n\n"
	return out
}

func renderCirclePath(rest string) string {
	rest = strings.Trim(rest, "/")
	parts := strings.Split(rest, "/")
	id := parseID(parts[0])
	if id == 0 {
		return notFound("circle/" + rest)
	}
	if len(parts) > 1 && parts[1] == "rules" {
		return renderRules(mustCircle(id))
	}
	return renderCircle(id)
}

func renderCircle(id uint64) string {
	c := mustCircle(id)
	now := time.Now()

	out := "# " + c.Name + "\n\n"
	out += ufmt.Sprintf("Circle #%d · created by %s on %s · status **%s**\n\n",
		c.ID, who(c.Creator), c.OpenedAt.Format("02 Jan 2006 15:04"), c.Status.String())

	out += ufmt.Sprintf("- Contribution: **%s per member per round**\n", money(c.Params.Contribution))
	out += ufmt.Sprintf("- Seats: **%d** (joined %d)\n", c.Params.Size, c.Seats())
	out += ufmt.Sprintf("- Round length: **%s**\n", rosca.HumanDuration(c.Params.RoundSpan))
	out += ufmt.Sprintf("- Collateral per seat: **%s**, returned when the circle closes\n\n", money(c.Params.Collateral))

	switch c.Status {
	case rosca.StatusOpen:
		out += openBody(c)
	case rosca.StatusActive:
		out += activeBody(c, now)
	case rosca.StatusComplete:
		out += completeBody(c)
	}

	out += "\n---\n\n## Members\n\n"
	out += memberTable(c)

	if len(c.Payouts) > 0 {
		out += "\n## Activity\n\n"
		out += payoutList(c)
	}

	out += "\n## Actions\n\n"
	out += actionLinks(c)
	out += "\n## Client\n\n```sh\n" + clientCLI(c) + "\n```\n"
	out += "\n_Secrets of the schedule: seed `" + c.Seed + "`_\n"
	return out
}

func openBody(c *Circle) string {
	seats := c.Seats()
	out := "\n"
	out += ufmt.Sprintf("**Collecting members** %s %d/%d\n\n", rosca.Bar(seats, c.Params.Size, 12), seats, c.Params.Size)
	out += ufmt.Sprintf("The circle activates automatically when the last seat is taken. Pot at activation: **%s**.\n\n",
		money(c.Params.Pot()))
	out += ufmt.Sprintf("[Join with %s collateral](%s) · [Leave and take collateral back](%s) · [Cancel circle](%s)\n",
		money(c.Params.Collateral), helpLink2("Join", "id", c.ID), helpLink2("Leave", "id", c.ID), helpLink2("Cancel", "id", c.ID))
	if seats >= c.Params.Size {
		out += "\n_Circle is full: activation happens on the next join attempt or page render cycle._\n"
	}
	return out
}

func activeBody(c *Circle, now time.Time) string {
	settled, planned := c.Progress()
	out := "\n"
	out += ufmt.Sprintf("**Rounds** %s %d/%d settled · now paying round **%d**\n\n",
		rosca.Bar(settled, planned, 12), settled, planned, c.Round+1)

	bi := c.NextBeneficiary()
	if bi >= 0 {
		out += ufmt.Sprintf("**Pot this round:** %s → next payment goes to %s\n\n",
			money(c.Params.Pot()), who(c.Members[bi].Addr))
	}

	rem := c.Remaining(now)
	if rem > 0 {
		out += ufmt.Sprintf("**Deadline:** %s (in %s) · block time %s\n\n",
			c.Deadline.Format("02 Jan 2006 15:04"), rosca.HumanDuration(rem), now.Format("02 Jan 2006 15:04"))
	} else {
		out += ufmt.Sprintf("**Deadline passed** %s ago · anyone may settle the round\n\n", rosca.HumanDuration(-rem))
	}

	paid := 0
	for _, m := range c.Members {
		if !m.Defaulted && m.PaidRound >= c.Round {
			paid++
		}
	}
	out += ufmt.Sprintf("**Paid this round:** %d of %d active members %s\n\n", paid, c.Active(), rosca.Bar(paid, c.Active(), 12))
	out += ufmt.Sprintf("[Pay %s now](%s) · [Settle defaults](%s)\n",
		money(c.Params.Contribution), helpLink2("Contribute", "id", c.ID), helpLink2("Advance", "id", c.ID))
	return out
}

func completeBody(c *Circle) string {
	out := "\n"
	if c.Cancelled {
		out += "**Circle cancelled.** Every seat was refunded; nothing was ever paid out as a pot.\n\n"
		return out
	}
	tmpl := "**Circle complete** on %s. Every member received the pot once, collateral came back, and the penalty fund was shared among honest members.\n\n"
	out += ufmt.Sprintf(tmpl, c.ClosedAt.Format("02 Jan 2006 15:04"))
	out += ufmt.Sprintf("Paid in %s · paid out %s · residual in realm %s\n\n",
		money(c.PaidInTotal), money(c.PaidOutTotal), money(c.Pool))
	return out
}

func memberTable(c *Circle) string {
	out := "| seat | member | paid rounds | collateral | pot received | status |\n"
	out += "| --- | --- | --- | --- | --- | --- |\n"
	for i, m := range c.Members {
		status := "on track"
		if m.Defaulted {
			status = "**defaulted**"
		} else if m.Received {
			status = "**paid out**"
		} else if c.Status == rosca.StatusActive && m.PaidRound < c.Round {
			status = "pending this round"
		}
		got := "—"
		if m.Received {
			got = "yes"
		}
		out += ufmt.Sprintf("| %d | %s | %d | %s | %s | %s |\n",
			i+1, who(m.Addr), m.RoundsPaid, money(m.Collateral), got, status)
	}
	return out
}

func payoutList(c *Circle) string {
	out := ""
	n := len(c.Payouts)
	start := 0
	if n > 12 {
		start = n - 12
	}
	if start > 0 {
		out += ufmt.Sprintf("_showing the last 12 of %d entries_\n\n", n)
	}
	for i := start; i < n; i++ {
		py := c.Payouts[i]
		label := py.Kind
		switch py.Kind {
		case "pot":
			label = "pot, round " + strconv.Itoa(py.Round+1)
		case "slash":
			label = "collateral slashed, round " + strconv.Itoa(py.Round+1)
		case "refund":
			label = "refund"
		}
		out += ufmt.Sprintf("- %s · **%s** → %s · _%s_\n",
			label, money(py.Amount), who(py.To), py.At.Format("02 Jan 15:04"))
	}
	return out + "\n"
}

func actionLinks(c *Circle) string {
	out := ""
	if c.Status == rosca.StatusOpen {
		out += ufmt.Sprintf("- [Join this circle](%s) — locks %s\n", helpLink2("Join", "id", c.ID), money(c.Params.Collateral))
		out += ufmt.Sprintf("- [Leave this circle](%s) — refunds your collateral\n", helpLink2("Leave", "id", c.ID))
		out += ufmt.Sprintf("- [Cancel this circle](%s) — creator only, refunds every seat\n", helpLink2("Cancel", "id", c.ID))
		return out
	}
	out += ufmt.Sprintf("- [Pay %s for round %d](%s)\n", money(c.Params.Contribution), c.Round+1, helpLink2("Contribute", "id", c.ID))
	out += ufmt.Sprintf("- [Settle defaults](%s) — usable once the deadline has passed\n", helpLink2("Advance", "id", c.ID))
	out += ufmt.Sprintf("- [Rules and guarantees](%s:circle/%d/rules)\n", pkgPath, c.ID)
	return out
}

func renderRules(c *Circle) string {
	out := "# How circle #" + strconv.FormatUint(c.ID, 10) + " settles\n\n"
	out += "This page is generated from the same code that runs the circle, not from a document "
	out += "someone edited after the fact.\n\n"
	out += "## The rotation\n\n"
	out += ufmt.Sprintf("1. **Join** locks %s of collateral, exactly one contribution.\n", money(c.Params.Collateral))
	out += "2. When the last seat fills, the circle **activates**. The payout order is a Fisher-Yates "
	out += "shuffle seeded with `sha256(circle id | activation height | sorted member addresses)`, so the "
	out += "creator cannot pick who gets paid first and every node derives the same order.\n"
	tmpl := "3. Each round, every active member pays **%s**. The moment the last one pays, the pot of **%s** is sent to the next member in the order — one transaction, no keeper.\n"
	out += ufmt.Sprintf(tmpl, money(c.Params.Contribution), money(c.Params.Pot()))
	out += "4. When every active member has received the pot once, the circle closes: collateral is returned "
	out += "and the penalty fund is split evenly among the members who never defaulted.\n\n"
	out += "## Defaults\n\n"
	tmplD := "- After the round deadline, **anyone** can call `Advance`. Every active member who did not pay is marked in default and their %s collateral moves to the penalty fund.\n"
	out += ufmt.Sprintf(tmplD, money(c.Params.Collateral))
	out += "- A defaulted member loses the seat, is skipped in the payout order, and gets no refund.\n"
	out += "- The pot released is what was actually collected, so the realm never pays out money it does not hold.\n\n"
	out += "## Why it balances\n\n"
	tmplB := "A member pays one contribution per round plus one collateral, receives the pot once, and gets the collateral back: net %s. Collateral exists only to make a skipped round cost more than the round itself.\n\n"
	out += ufmt.Sprintf(tmplB, money(c.Params.NetPerMember()))
	out += "Every payout is subtracted from that circle's own pool before the transfer, and the realm "
	out += "panics if a payout would ever exceed it.\n"
	return out
}

func renderAbout() string {
	out := "# How Kolektif works\n\n"
	out += "A ROSCA (rotating savings and credit association) is how most of the world saves without a bank: "
	out += "a group agrees on a fixed amount, everyone pays it every round, and each round one member takes "
	out += "the whole pot. Repeat until everyone has had a turn.\n\n"
	out += "Kolektif puts that on Gno.land, where it finally has the two things a group of neighbours cannot "
	out += "give each other: an escrow that nobody can walk away with, and a payout order nobody can argue about.\n\n"
	out += "## What the chain enforces\n\n"
	out += "- **Custody.** Contributions land on the realm address. A payout is a `banker.SendCoins` from the "
	out += "circle's own pool, checked before it is sent, so the realm cannot overpay.\n"
	out += "- **Order.** At activation the order is derived from the circle id, the activation height and the "
	out += "sorted member set. Change one member and the order changes; the creator has no lever.\n"
	out += "- **Missed rounds.** Collateral is slashed automatically by `Advance`, which anyone can call after "
	out += "the deadline. No admin decides who defaulted: the clock does.\n"
	out += "- **Balance.** With no defaults a member pays exactly what they receive. The penalty fund is the "
	out += "only thing that moves value between members, and it moves from defaulters to the honest.\n\n"
	out += "## Why a circle and not a loan\n\n"
	out += "There is no interest, no oracle, no collateral liquidation and no counterparty risk beyond the "
	out += "group: the pot is the group's own money, rotating. That is why ROSCAs survive in places with no "
	out += "credit infrastructure, and why they are a better first app for a chain than another AMM.\n\n"
	out += "## For builders\n\n"
	out += "The economics live in a pure package, `rosca`, that any realm can import: the payout schedule, "
	out += "the split of a penalty fund, the GNOT formatting, the progress bar. This realm is the reference "
	out += "implementation of that package, and the read-only API (`CircleSummary`, `IsMember`, `Standing`) "
	out += "lets another realm gate on membership without touching this realm's state.\n\n"
	out += "[Back to the circles](" + pkgPath + ")\n"
	return out
}

func renderMember(a address) string {
	if !a.IsValid() {
		return notFound("member/" + a.String())
	}
	out := "# " + who(a) + "\n\n"
	out += "`" + a.String() + "`\n\n"

	found := false
	for _, c := range circles {
		m := c.Member(a)
		if m == nil {
			continue
		}
		if !found {
			out += "## Seats\n\n| circle | paid | collateral | pot | status |\n| --- | --- | --- | --- | --- |\n"
			found = true
		}
		status := "on track"
		if m.Defaulted {
			status = "**defaulted**"
		}
		pot := "—"
		if m.Received {
			pot = "received"
		}
		out += ufmt.Sprintf("| [%s](%s:circle/%d) | %d | %s | %s | %s |\n",
			c.Name, pkgPath, c.ID, m.RoundsPaid, money(m.Collateral), pot, status)
	}
	if !found {
		out += "_No seat in any circle yet._\n"
	}
	return out
}

// --- helpers -----------------------------------------------------------

func money(ugnot int64) string {
	return rosca.Gnot(ugnot) + " GNOT"
}

func who(a address) string {
	u := users.ResolveAddress(a)
	if u != nil {
		return u.RenderLink("")
	}
	return "`" + rosca.ShortAddr(a.String()) + "`"
}

func helpLink(fn string) string {
	return pkgPath + "$help&func=" + fn
}

func helpLink2(fn, key string, id uint64) string {
	return pkgPath + "$help&func=" + fn + "&" + key + "=" + strconv.FormatUint(id, 10)
}

func parseID(s string) uint64 {
	id, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0
	}
	return id
}

func notFound(path string) string {
	return "# Not found\n\nNo page for `" + path + "`.\n\n[Back to the circles](" + pkgPath + ")\n"
}

func createCLI() string {
	return "gnokey maketx call -pkgpath \"" + pkgPath + "\" \\\n" +
		"  -func \"Create\" -args \"Warung Crew\" -args 1000000 -args 3 -args 300 \\\n" +
		"  -gas-fee 1000000ugnot -gas-wanted 50000000 \\\n" +
		"  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 chime"
}

func clientCLI(c *Circle) string {
	base := "gnokey maketx call -pkgpath \"" + pkgPath + "\" \\\n  -func \"Contribute\" -args " + strconv.FormatUint(c.ID, 10) + " \\\n" +
		"  -send \"" + strconv.FormatInt(c.Params.Contribution, 10) + "ugnot\" \\\n" +
		"  -gas-fee 1000000ugnot -gas-wanted 50000000 \\\n" +
		"  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 chime"
	return base
}

package kolektif

import (
	"time"

	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif/rosca"
)

// Member is one seat in a circle.
type Member struct {
	Addr       address
	Collateral int64 // ugnot still held as collateral for this member
	PaidRound  int   // highest round this member paid; -1 before the first payment
	RoundsPaid int
	Defaulted  bool
	Received   bool
	JoinedAt   time.Time
}

// Payout records one distribution out of the circle.
type Payout struct {
	Round  int
	To     address
	Amount int64
	At     time.Time
	Kind   string // "pot", "collateral", "penalty", "refund"
}

// Circle is one rotating savings circle.
type Circle struct {
	ID              uint64
	Name            string
	Creator         address
	Params          rosca.Params
	Members         []*Member
	Order           []int // payout order, indexes into Members
	Round           int
	Status          rosca.Status
	OpenedAt        time.Time
	ActivatedAt     time.Time
	Deadline        time.Time
	Pool            int64 // ugnot held by the realm on behalf of this circle
	Penalty         int64 // slashed collateral waiting to be shared out
	Payouts         []Payout
	ClosedAt        time.Time
	Cancelled       bool
	Seed            string
	ActivateHeight  int64
	PaidInTotal     int64 // lifetime contributions received
	PaidOutTotal    int64
}

// Member returns the seat of addr, or nil.
func (c *Circle) Member(addr address) *Member {
	for _, m := range c.Members {
		if m.Addr == addr {
			return m
		}
	}
	return nil
}

// Seats returns the number of joined members.
func (c *Circle) Seats() int {
	return len(c.Members)
}

// Active returns the number of members that are not defaulted.
func (c *Circle) Active() int {
	n := 0
	for _, m := range c.Members {
		if !m.Defaulted {
			n++
		}
	}
	return n
}

// RoundsPlanned is how many payouts the circle still owes.
func (c *Circle) RoundsPlanned() int {
	n := 0
	for _, m := range c.Members {
		if !m.Defaulted {
			n++
		}
	}
	return n
}

// RoundsSettled counts completed payouts.
func (c *Circle) RoundsSettled() int {
	n := 0
	for _, m := range c.Members {
		if m.Received {
			n++
		}
	}
	return n
}

// NextBeneficiary returns the member index that receives the current round's
// pot, or -1 when nobody is left to pay.
func (c *Circle) NextBeneficiary() int {
	for _, idx := range c.Order {
		if idx < 0 || idx >= len(c.Members) {
			continue
		}
		m := c.Members[idx]
		if !m.Received && !m.Defaulted {
			return idx
		}
	}
	return -1
}

// RoundPaid reports whether every active member has paid the current round.
func (c *Circle) RoundPaid() bool {
	for _, m := range c.Members {
		if m.Defaulted {
			continue
		}
		if m.PaidRound < c.Round {
			return false
		}
	}
	return true
}

// Remaining is the time left in the current round, in seconds.
func (c *Circle) Remaining(now time.Time) int64 {
	if c.Status != rosca.StatusActive {
		return 0
	}
	return c.Deadline.Unix() - now.Unix()
}

// Progress is the share of scheduled payouts already delivered.
func (c *Circle) Progress() (int, int) {
	return c.RoundsSettled(), c.RoundsPlanned()
}

// Package probe measures how long a package waits for approval on Onyx.
package probe

import "strconv"

var (
	count int
	last  address
)

// Bump increments the counter, remembers the caller and returns the new count.
func Bump(cur realm) int {
	count++
	last = cur.Previous().Address()
	return count
}

func Render(path string) string {
	s := "# probe\n\nCounter: " + strconv.Itoa(count) + "\n"
	if last != "" {
		s += "\nLast caller: " + last.String() + "\n"
	}
	return s
}

package probe

// Ping returns a constant: the smallest possible package.
func Ping() string { return "pong" }

package tankardtales

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// Posting a quest (the only function that takes money)
// ---------------------------------------------------------------------------

// PostQuest pins a new quest to the board and locks its tip in escrow.
//
// The tip must arrive with the call itself: the caller attaches exactly
// `tip` ugnot via `maketx call -send <tip>ugnot`. Following the upstream
// payment-verification pattern, the call must come straight from a user
// (no intermediate or ephemeral realm may touch the send envelope first)
// and the envelope must contain exactly the declared tip — no more, no
// less, and nothing in any other denom. The coins land in the realm's own
// account, where they sit until CompleteQuest pays them to the adventurer
// or CancelQuest refunds them to the poster.
//
// Returns the new quest's ID as a decimal string.
func PostQuest(cur realm, title, details string, tip int64) string {
	if !cur.Previous().IsUserCall() {
		panic("quest: PostQuest must be called directly by a user")
	}
	poster := cur.Previous().Address()

	verifyTipPayment(tip)

	id := postQuest(poster, title, details, tip)

	chain.Emit("QuestPosted",
		"id", strconv.Itoa(id),
		"poster", poster.String(),
		"tip", strconv.FormatInt(tip, 10),
	)
	return strconv.Itoa(id)
}

// verifyTipPayment checks that exactly `tip` ugnot was sent with the call.
func verifyTipPayment(tip int64) {
	if tip < MinTipUgnot {
		panic("quest: tip is below the minimum of 1000ugnot")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != tip {
		panic("quest: send exactly the tip amount in ugnot with this call")
	}
}

// postQuest is the state transition behind PostQuest, split out so the
// board logic can be unit-tested without a payment envelope.
func postQuest(poster address, title, details string, tip int64) int {
	title = strings.TrimSpace(title)
	details = strings.TrimSpace(details)
	if len(title) < 3 || len(title) > MaxTitleLen {
		panic("quest: title must be 3-80 characters")
	}
	if len(details) == 0 || len(details) > MaxDetailsLen {
		panic("quest: details must be 1-1000 characters")
	}
	if tip < MinTipUgnot {
		panic("quest: tip is below the minimum of 1000ugnot")
	}

	questSeq++
	q := &Quest{
		ID:      questSeq,
		Poster:  poster,
		Title:   title,
		Details: details,
		Tip:     tip,
		Status:  StatusOpen,
	}
	questsTree.Set(strconv.Itoa(q.ID), q)
	escrowUgnot += tip

	reg := regularOf(poster)
	reg.QuestsPosted++
	regularsTree.Set(poster.String(), reg)

	return q.ID
}

// ---------------------------------------------------------------------------
// Working a quest
// ---------------------------------------------------------------------------

// ClaimQuest makes the caller the one adventurer working on an open quest.
// A poster cannot claim their own quest — no paying yourself, friend.
func ClaimQuest(cur realm, id string) {
	caller := cur.Previous().Address()
	q := mustQuest(id)

	if q.Status != StatusOpen {
		panic("quest: not open for claiming")
	}
	if caller == q.Poster {
		panic("quest: you cannot claim your own quest")
	}

	q.Status = StatusClaimed
	q.Claimer = caller
	questsTree.Set(id, q)

	chain.Emit("QuestClaimed", "id", id, "claimer", caller.String())
}

// AbandonQuest releases a claimed quest back to the board. Only the
// current claimer may abandon it; the tip stays in escrow.
func AbandonQuest(cur realm, id string) {
	caller := cur.Previous().Address()
	q := mustQuest(id)

	if q.Status != StatusClaimed {
		panic("quest: not claimed")
	}
	if caller != q.Claimer {
		panic("quest: only the claimer can abandon this quest")
	}

	q.Status = StatusOpen
	q.Claimer = address("")
	questsTree.Set(id, q)

	chain.Emit("QuestAbandoned", "id", id, "claimer", caller.String())
}

// CompleteQuest is the poster confirming the work is done. The escrowed
// tip moves from the realm's account to the claimer, and the claimer's
// regulars tally grows. This is the moment the tavern lives for.
func CompleteQuest(cur realm, id string) {
	caller := cur.Previous().Address()
	q := mustQuest(id)

	if caller != q.Poster {
		panic("quest: only the poster can complete this quest")
	}
	if q.Status != StatusClaimed {
		panic("quest: not claimed, so it cannot be completed")
	}

	claimer := q.Claimer
	tip := q.Tip

	banker_ := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	banker_.SendCoins(cur.Address(), claimer, chain.NewCoins(chain.NewCoin("ugnot", tip)))

	q.Status = StatusCompleted
	questsTree.Set(id, q)
	escrowUgnot -= tip

	reg := regularOf(claimer)
	reg.QuestsDone++
	reg.TipsEarned += tip
	regularsTree.Set(claimer.String(), reg)

	chain.Emit("QuestCompleted",
		"id", id,
		"claimer", claimer.String(),
		"tip", strconv.FormatInt(tip, 10),
	)
}

// CancelQuest takes an unclaimed quest off the board and refunds the
// escrowed tip to the poster. A claimed quest cannot be cancelled out
// from under its adventurer — they must abandon it first.
func CancelQuest(cur realm, id string) {
	caller := cur.Previous().Address()
	q := mustQuest(id)

	if caller != q.Poster {
		panic("quest: only the poster can cancel this quest")
	}
	if q.Status != StatusOpen {
		panic("quest: only an open (unclaimed) quest can be cancelled")
	}

	tip := q.Tip

	banker_ := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	banker_.SendCoins(cur.Address(), q.Poster, chain.NewCoins(chain.NewCoin("ugnot", tip)))

	q.Status = StatusCancelled
	questsTree.Set(id, q)
	escrowUgnot -= tip

	chain.Emit("QuestCancelled",
		"id", id,
		"poster", q.Poster.String(),
		"tip", strconv.FormatInt(tip, 10),
	)
}

// ---------------------------------------------------------------------------
// Reading the board
// ---------------------------------------------------------------------------

// mustQuest loads a quest or panics trying.
func mustQuest(id string) *Quest {
	v := questsTree.Get(id)
	if v == nil {
		panic("quest: no quest with id " + id)
	}
	return v.(*Quest)
}

// GetQuest returns one quest's public fields.
func GetQuest(id string) (poster address, title, details string, tip int64, status string, claimer address, ok bool) {
	v := questsTree.Get(id)
	if v == nil {
		return "", "", "", 0, "", "", false
	}
	q := v.(*Quest)
	return q.Poster, q.Title, q.Details, q.Tip, q.Status, q.Claimer, true
}

// QuestCount returns how many quests have ever been posted.
func QuestCount() int {
	return questSeq
}

// OpenQuestCount returns how many quests are open or claimed right now.
func OpenQuestCount() int {
	n := 0
	questsTree.Iterate("", "", func(_ string, v any) bool {
		q := v.(*Quest)
		if q.Status == StatusOpen || q.Status == StatusClaimed {
			n++
		}
		return false
	})
	return n
}

// allQuests returns every quest, in posting order. Render paths sort and
// trim the result themselves; the board is small by design.
func allQuests() []*Quest {
	out := make([]*Quest, 0, questsTree.Size())
	questsTree.Iterate("", "", func(_ string, v any) bool {
		out = append(out, v.(*Quest))
		return false
	})
	return out
}

package tankardtales

import (
	"chain"
	"chain/banker"
	"strconv"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

const pkgPath = "gno.land/r/nym-kaycee042/tankardtales"

// fundRealm gives the realm's own account a working balance, the way a
// real deployment accumulates escrowed tips.
func fundRealm(cur realm, amount int64) {
	realmAddr := chain.PackageAddress(pkgPath)
	testing.IssueCoins(realmAddr, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

func ugnotBalance(cur realm, addr address) int64 {
	banker_ := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	return banker_.GetCoin(addr, "ugnot")
}

func TestQuestLifecycle(cur realm, t *testing.T) {
	fundRealm(cur, 1_000_000)
	escrowBefore := EscrowUgnot()
	_, bobDone0, bobTips0, _, _ := GetRegular(bob)
	alicePosted0, _, _, _, _ := GetRegular(alice)

	// Alice posts; the internal helper stands in for the payment-checked
	// public entry point (covered separately in TestPostQuestPayment).
	id := postQuest(alice, "Slay the spam bots", "Clear the tavern noticeboard of spam.", 5000)
	idStr := strconv.Itoa(id)

	poster, title, _, tip, status, _, ok := GetQuest(idStr)
	uassert.Equal(t, ok, true)
	uassert.Equal(t, poster, alice)
	uassert.Equal(t, title, "Slay the spam bots")
	uassert.Equal(t, tip, int64(5000))
	uassert.Equal(t, status, StatusOpen)
	uassert.Equal(t, EscrowUgnot(), escrowBefore+5000)

	// Bob claims it.
	testing.SetRealm(testing.NewUserRealm(bob))
	ClaimQuest(cross(cur), idStr)
	_, _, _, _, status, claimer, _ := GetQuest(idStr)
	uassert.Equal(t, status, StatusClaimed)
	uassert.Equal(t, claimer, bob)

	// Alice confirms the work; the tip moves to Bob.
	bobBefore := ugnotBalance(cur, bob)
	testing.SetRealm(testing.NewUserRealm(alice))
	CompleteQuest(cross(cur), idStr)

	_, _, _, _, status, _, _ = GetQuest(idStr)
	uassert.Equal(t, status, StatusCompleted)
	uassert.Equal(t, EscrowUgnot(), escrowBefore)
	uassert.Equal(t, ugnotBalance(cur, bob), bobBefore+5000)

	// Bob's regulars tally tells the story (delta-based: other tests
	// in the package may share realm state within one run).
	_, done, tipsEarned, _, ok := GetRegular(bob)
	uassert.Equal(t, ok, true)
	uassert.Equal(t, done, bobDone0+1)
	uassert.Equal(t, tipsEarned, bobTips0+5000)

	// And Alice is recorded as the poster.
	posted, _, _, _, _ := GetRegular(alice)
	uassert.Equal(t, posted, alicePosted0+1)
}

func TestClaimRules(cur realm, t *testing.T) {
	idStr := strconv.Itoa(postQuest(carol, "Tune the tavern lute", "It has been flat since spring.", 2000))

	// The poster cannot claim their own quest.
	testing.SetRealm(testing.NewUserRealm(carol))
	expectPanic(t, cur, "you cannot claim your own quest", func() {
		ClaimQuest(cross(cur), idStr)
	})

	// Dave claims; now nobody else can.
	testing.SetRealm(testing.NewUserRealm(dave))
	ClaimQuest(cross(cur), idStr)
	testing.SetRealm(testing.NewUserRealm(bob))
	expectPanic(t, cur, "not open for claiming", func() {
		ClaimQuest(cross(cur), idStr)
	})

	// Claiming a quest that does not exist panics too.
	expectPanic(t, cur, "no quest with id", func() {
		ClaimQuest(cross(cur), "999999")
	})
}

func TestAbandonAndReclaim(cur realm, t *testing.T) {
	idStr := strconv.Itoa(postQuest(alice, "Polish the tankards", "All forty of them. To a shine.", 3000))

	testing.SetRealm(testing.NewUserRealm(bob))
	ClaimQuest(cross(cur), idStr)

	// Only the claimer may abandon.
	testing.SetRealm(testing.NewUserRealm(carol))
	expectPanic(t, cur, "only the claimer can abandon this quest", func() {
		AbandonQuest(cross(cur), idStr)
	})

	testing.SetRealm(testing.NewUserRealm(bob))
	AbandonQuest(cross(cur), idStr)
	_, _, _, _, status, claimer, _ := GetQuest(idStr)
	uassert.Equal(t, status, StatusOpen)
	uassert.Equal(t, claimer, address(""))

	// Someone else can pick it up afterwards.
	testing.SetRealm(testing.NewUserRealm(carol))
	ClaimQuest(cross(cur), idStr)
	_, _, _, _, status, claimer, _ = GetQuest(idStr)
	uassert.Equal(t, status, StatusClaimed)
	uassert.Equal(t, claimer, carol)
}

func TestCompleteRules(cur realm, t *testing.T) {
	idStr := strconv.Itoa(postQuest(alice, "Mend the tavern roof", "It leaks into the ale.", 4000))

	// An unclaimed quest cannot be completed.
	testing.SetRealm(testing.NewUserRealm(alice))
	expectPanic(t, cur, "not claimed, so it cannot be completed", func() {
		CompleteQuest(cross(cur), idStr)
	})

	testing.SetRealm(testing.NewUserRealm(bob))
	ClaimQuest(cross(cur), idStr)

	// Only the poster can complete it.
	testing.SetRealm(testing.NewUserRealm(carol))
	expectPanic(t, cur, "only the poster can complete this quest", func() {
		CompleteQuest(cross(cur), idStr)
	})
}

func TestCancelQuestRefunds(cur realm, t *testing.T) {
	fundRealm(cur, 1_000_000)
	escrowBefore := EscrowUgnot()

	idStr := strconv.Itoa(postQuest(carol, "Sweep the cellar", "Mind the barrels.", 6000))
	uassert.Equal(t, EscrowUgnot(), escrowBefore+6000)

	// A claimed quest cannot be cancelled from under its adventurer.
	testing.SetRealm(testing.NewUserRealm(dave))
	ClaimQuest(cross(cur), idStr)
	testing.SetRealm(testing.NewUserRealm(carol))
	expectPanic(t, cur, "only an open (unclaimed) quest can be cancelled", func() {
		CancelQuest(cross(cur), idStr)
	})

	// Dave abandons; now Carol can cancel and gets her tip back.
	testing.SetRealm(testing.NewUserRealm(dave))
	AbandonQuest(cross(cur), idStr)

	carolBefore := ugnotBalance(cur, carol)
	testing.SetRealm(testing.NewUserRealm(carol))
	CancelQuest(cross(cur), idStr)

	_, _, _, _, status, _, _ := GetQuest(idStr)
	uassert.Equal(t, status, StatusCancelled)
	uassert.Equal(t, EscrowUgnot(), escrowBefore)
	uassert.Equal(t, ugnotBalance(cur, carol), carolBefore+6000)
}

func TestPostQuestPayment(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(dave))
	escrowBefore := EscrowUgnot()

	// Exact tip attached: quest lands on the board.
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 7000)))
	idStr := PostQuest(cross(cur), "Fetch the golden tankard", "It is in the cellar. Mind the gnome.", 7000)
	poster, _, _, tip, status, _, ok := GetQuest(idStr)
	uassert.Equal(t, ok, true)
	uassert.Equal(t, poster, dave)
	uassert.Equal(t, tip, int64(7000))
	uassert.Equal(t, status, StatusOpen)
	uassert.Equal(t, EscrowUgnot(), escrowBefore+7000)

	// Sending less than the declared tip is rejected.
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1)))
	expectPanic(t, cur, "send exactly the tip amount in ugnot", func() {
		PostQuest(cross(cur), "A dubious quest", "Perfectly normal details.", 7000)
	})

	// A tip under the minimum is rejected even if the send matches.
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 10)))
	expectPanic(t, cur, "tip is below the minimum", func() {
		PostQuest(cross(cur), "A cheap quest", "Perfectly normal details.", 10)
	})

	// Nothing extra reached the board or the escrow.
	uassert.Equal(t, EscrowUgnot(), escrowBefore+7000)
}

package tankardtales

import (
	"bytes"
	"sort"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/ufmt/v0"
)

// BaseURL is the realm's gnoweb path. It must match the module path in
// gnomod.toml (minus the gno.land prefix) — if the deploy path changes,
// change both together.
const BaseURL = "/r/nym-kaycee042/tankardtales"

var router = mux.NewRouter()

func init() {
	router.HandleFunc("", homeHandler)
	router.HandleFunc("quests", questsHandler)
	router.HandleFunc("quests/{id}", questHandler)
	router.HandleFunc("guestbook", guestbookHandler)
	router.HandleFunc("regulars", regularsHandler)
}

// Render is the realm's gnoweb entry point.
func Render(path string) string {
	return router.Render(path)
}

// tipString formats an amount of ugnot for display.
func tipString(amt int64) string {
	if amt >= 1_000_000 && amt%1_000_000 == 0 {
		return ufmt.Sprintf("%d GNOT", amt/1_000_000)
	}
	return ufmt.Sprintf("%d ugnot", amt)
}

func homeHandler(res *mux.ResponseWriter, req *mux.Request) {
	var b bytes.Buffer

	b.WriteString("# Tankard & Tales\n\n")
	b.WriteString("Welcome to the tavern, traveller. Sign the guestbook, " +
		"take a quest from the board, and earn real testnet GNOT for honest work — " +
		"every tip is held in escrow by this realm and paid out on completion.\n\n")

	b.WriteString("## The tavern tonight\n\n")
	b.WriteString(ufmt.Sprintf("- Quests posted: **%d** (%d live)\n", QuestCount(), OpenQuestCount()))
	b.WriteString(ufmt.Sprintf("- Guests in the book: **%d**\n", GuestCount()))
	b.WriteString(ufmt.Sprintf("- Tips in escrow: **%s**\n\n", tipString(EscrowUgnot())))

	b.WriteString("## Pull up a stool\n\n")
	b.WriteString(ufmt.Sprintf("- [Sign the guestbook](%s$help&func=SignGuestbook)\n", BaseURL))
	b.WriteString(ufmt.Sprintf("- [Post a quest](%s$help&func=PostQuest) — attach the tip with your call\n", BaseURL))
	b.WriteString(ufmt.Sprintf("- [Browse the quest board](%s:quests)\n", BaseURL))
	b.WriteString(ufmt.Sprintf("- [Read the guestbook](%s:guestbook)\n", BaseURL))
	b.WriteString(ufmt.Sprintf("- [Meet the regulars](%s:regulars)\n\n", BaseURL))

	latest := latestQuests(5)
	if len(latest) > 0 {
		b.WriteString("## Fresh on the board\n\n")
		for _, q := range latest {
			writeQuestLine(&b, q)
		}
	}

	res.Write(b.String())
}

func questsHandler(res *mux.ResponseWriter, req *mux.Request) {
	var b bytes.Buffer

	b.WriteString("# The Quest Board\n\n")
	b.WriteString(ufmt.Sprintf("Every notice here carries a tip locked in escrow. " +
		"Claim one, do the work, and the poster releases the tip to you.\n\n"))
	b.WriteString(ufmt.Sprintf("[Post your own quest](%s$help&func=PostQuest)\n\n", BaseURL))

	qs := latestQuests(25)
	if len(qs) == 0 {
		b.WriteString("The board is bare. Nail up the first quest.\n")
	}
	for _, q := range qs {
		writeQuestLine(&b, q)
	}

	res.Write(b.String())
}

func questHandler(res *mux.ResponseWriter, req *mux.Request) {
	var b bytes.Buffer
	id := req.GetVar("id")

	v := questsTree.Get(id)
	if v == nil {
		b.WriteString("# No such quest\n\n")
		b.WriteString(ufmt.Sprintf("There is no quest #%s on this board. [Back to the board](%s:quests)\n", sanitize.InlineText(id), BaseURL))
		res.Write(b.String())
		return
	}
	q := v.(*Quest)

	b.WriteString(ufmt.Sprintf("# Quest #%d: %s\n\n", q.ID, sanitize.InlineText(q.Title)))
	b.WriteString(ufmt.Sprintf("- Status: **%s**\n", q.Status))
	b.WriteString(ufmt.Sprintf("- Tip: **%s** (in escrow)\n", tipString(q.Tip)))
	b.WriteString(ufmt.Sprintf("- Posted by: %s\n", q.Poster.String()))
	if q.Claimer != address("") {
		b.WriteString(ufmt.Sprintf("- Claimed by: %s\n", q.Claimer.String()))
	}
	b.WriteString("\n")
	b.WriteString(sanitize.Block(q.Details))
	b.WriteString("\n\n")

	switch q.Status {
	case StatusOpen:
		b.WriteString(ufmt.Sprintf("[Claim this quest](%s$help&func=ClaimQuest&id=%d)\n", BaseURL, q.ID))
	case StatusClaimed:
		b.WriteString(ufmt.Sprintf("If you posted this quest and the work is done: [mark it complete](%s$help&func=CompleteQuest&id=%d) to release the tip.\n", BaseURL, q.ID))
	}

	res.Write(b.String())
}

func guestbookHandler(res *mux.ResponseWriter, req *mux.Request) {
	var b bytes.Buffer

	b.WriteString("# The Guestbook\n\n")
	b.WriteString(ufmt.Sprintf("[Sign the guestbook](%s$help&func=SignGuestbook)\n\n", BaseURL))

	entries := sortedGuests(50)
	if len(entries) == 0 {
		b.WriteString("No signatures yet. The first round is on the house.\n")
	}
	for _, e := range entries {
		b.WriteString(ufmt.Sprintf("- **%s** — %s\n",
			sanitize.InlineText(e.entry.Name),
			sanitize.InlineText(e.entry.Message),
		))
	}

	res.Write(b.String())
}

func regularsHandler(res *mux.ResponseWriter, req *mux.Request) {
	var b bytes.Buffer

	b.WriteString("# The Regulars\n\n")
	b.WriteString("Ranked by tips earned. Complete quests, climb the board, " +
		"become a tavern legend.\n\n")

	regs := sortedRegulars(20)
	if len(regs) == 0 {
		b.WriteString("No regulars yet. The stools are empty and waiting.\n")
	}
	for i, r := range regs {
		b.WriteString(ufmt.Sprintf("%d. %s — %d quests done, %s earned, %d posted\n",
			i+1, r.addr, r.reg.QuestsDone, tipString(r.reg.TipsEarned), r.reg.QuestsPosted))
	}

	res.Write(b.String())
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func writeQuestLine(b *bytes.Buffer, q *Quest) {
	b.WriteString(ufmt.Sprintf("- [#%d %s](%s:quests/%d) — %s — **%s** — posted by %s\n",
		q.ID,
		sanitize.InlineText(q.Title),
		BaseURL, q.ID,
		q.Status,
		tipString(q.Tip),
		q.Poster.String(),
	))
}

// Sortable views over the realm's rows. Gno's sort package offers the
// classic Interface-based API (no sort.Slice), so each row type gets a
// small named slice type implementing Len/Less/Swap.

type questsByIDDesc []*Quest

func (s questsByIDDesc) Len() int           { return len(s) }
func (s questsByIDDesc) Less(i, j int) bool { return s[i].ID > s[j].ID }
func (s questsByIDDesc) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

// latestQuests returns up to n quests, newest first.
func latestQuests(n int) []*Quest {
	qs := allQuests()
	sort.Sort(questsByIDDesc(qs))
	if len(qs) > n {
		qs = qs[:n]
	}
	return qs
}

type guestRow struct {
	addr  string
	entry *GuestEntry
}

type guestRows []guestRow

func (s guestRows) Len() int { return len(s) }
func (s guestRows) Less(i, j int) bool {
	if s[i].entry.Signs != s[j].entry.Signs {
		return s[i].entry.Signs > s[j].entry.Signs
	}
	return s[i].addr < s[j].addr
}
func (s guestRows) Swap(i, j int) { s[i], s[j] = s[j], s[i] }

// sortedGuests returns guestbook entries, most visits first.
func sortedGuests(n int) []guestRow {
	rows := make([]guestRow, 0, guestbookTree.Size())
	guestbookTree.Iterate("", "", func(key string, v any) bool {
		rows = append(rows, guestRow{addr: key, entry: v.(*GuestEntry)})
		return false
	})
	sort.Sort(guestRows(rows))
	if len(rows) > n {
		rows = rows[:n]
	}
	return rows
}

type regularRow struct {
	addr string
	reg  *Regular
}

type regularRows []regularRow

func (s regularRows) Len() int { return len(s) }
func (s regularRows) Less(i, j int) bool {
	if s[i].reg.TipsEarned != s[j].reg.TipsEarned {
		return s[i].reg.TipsEarned > s[j].reg.TipsEarned
	}
	if s[i].reg.QuestsDone != s[j].reg.QuestsDone {
		return s[i].reg.QuestsDone > s[j].reg.QuestsDone
	}
	return s[i].addr < s[j].addr
}
func (s regularRows) Swap(i, j int) { s[i], s[j] = s[j], s[i] }

// sortedRegulars returns the leaderboard: tips earned, then quests done.
func sortedRegulars(n int) []regularRow {
	rows := make([]regularRow, 0, regularsTree.Size())
	regularsTree.Iterate("", "", func(key string, v any) bool {
		rows = append(rows, regularRow{addr: key, reg: v.(*Regular)})
		return false
	})
	sort.Sort(regularRows(rows))
	if len(rows) > n {
		rows = rows[:n]
	}
	return rows
}

