// Package tankardtales is the realm behind Tankard & Tales, a tavern-themed
// quest board and guestbook that lives entirely on Gno.land.
//
// Every visitor can sign the tavern guestbook, post a quest with a tip held
// in escrow by the realm itself, claim somebody else's quest, and get paid
// the moment the poster confirms the work is done. Regulars earn a place on
// the leaderboard for quests completed and tips earned.
//
// The realm is deliberately self-contained: three AVL trees hold all state,
// no external realm is ever called, and no wall-clock value is ever read, so
// every state transition is deterministic and replayable.
package tankardtales

import (
	"chain"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Quest lifecycle states. A quest is born Open, may be Claimed by one
// adventurer at a time, and ends either Completed (tip paid out) or
// Cancelled (tip refunded to the poster).
const (
	StatusOpen      = "OPEN"
	StatusClaimed   = "CLAIMED"
	StatusCompleted = "COMPLETED"
	StatusCancelled = "CANCELLED"
)

// Input and economy limits. They keep the tavern tidy: long enough for real
// quests and messages, short enough that Render output stays readable and
// nobody can bloat state with essays.
const (
	// MinTipUgnot is the smallest tip a quest may carry: 0.001 GNOT.
	// A quest with no skin in the game is just a notice on the board.
	MinTipUgnot int64 = 1000

	MaxNameLen    = 32   // guestbook display name, bytes
	MaxMessageLen = 280  // guestbook message, bytes
	MaxTitleLen   = 80   // quest title, bytes
	MaxDetailsLen = 1000 // quest details, bytes
)

// Quest is one notice pinned to the tavern board.
type Quest struct {
	ID      int
	Poster  address
	Title   string
	Details string
	Tip     int64 // ugnot, held in escrow by the realm while the quest is live
	Status  string
	Claimer address // zero address while unclaimed
}

// GuestEntry is one signature in the tavern guestbook.
type GuestEntry struct {
	Name    string
	Message string
	Signs   int // how many times this guest has signed (they keep coming back)
}

// Regular is the running tally that feeds the regulars leaderboard.
type Regular struct {
	QuestsPosted int
	QuestsDone   int
	TipsEarned   int64 // ugnot earned by completing quests
	GuestSigns   int
}

var (
	questsTree    = avl.NewTree() // quest ID (decimal string) -> *Quest
	guestbookTree = avl.NewTree() // guest address string -> *GuestEntry
	regularsTree  = avl.NewTree() // address string -> *Regular

	questSeq    int   // monotonic quest counter; quest IDs start at 1
	escrowUgnot int64 // sum of tips currently locked in live quests
)

// ---------------------------------------------------------------------------
// Guestbook
// ---------------------------------------------------------------------------

// SignGuestbook signs the tavern guestbook, or updates an existing
// signature. Signing again refreshes the name and message and counts as
// another visit — the barkeep remembers regulars.
func SignGuestbook(cur realm, name, message string) {
	caller := cur.Previous().Address()

	name = strings.TrimSpace(name)
	message = strings.TrimSpace(message)
	if len(name) == 0 || len(name) > MaxNameLen {
		panic("guestbook: display name must be 1-32 characters")
	}
	if len(message) == 0 || len(message) > MaxMessageLen {
		panic("guestbook: message must be 1-280 characters")
	}

	key := caller.String()
	if v := guestbookTree.Get(key); v != nil {
		entry := v.(*GuestEntry)
		entry.Name = name
		entry.Message = message
		entry.Signs++
		guestbookTree.Set(key, entry)
	} else {
		guestbookTree.Set(key, &GuestEntry{Name: name, Message: message, Signs: 1})
	}

	reg := regularOf(caller)
	reg.GuestSigns++
	regularsTree.Set(key, reg)

	chain.Emit("GuestSigned", "guest", caller.String())
}

// GetGuest returns the guestbook entry for addr, if any.
func GetGuest(addr address) (name, message string, signs int, ok bool) {
	v := guestbookTree.Get(addr.String())
	if v == nil {
		return "", "", 0, false
	}
	entry := v.(*GuestEntry)
	return entry.Name, entry.Message, entry.Signs, true
}

// GuestCount returns how many distinct guests have signed the guestbook.
func GuestCount() int {
	return guestbookTree.Size()
}

// ---------------------------------------------------------------------------
// Regulars
// ---------------------------------------------------------------------------

// regularOf returns the (possibly newly created) tally for addr.
// It is only called from state-mutating flows; read paths use GetRegular.
func regularOf(addr address) *Regular {
	key := addr.String()
	if v := regularsTree.Get(key); v != nil {
		return v.(*Regular)
	}
	reg := &Regular{}
	regularsTree.Set(key, reg)
	return reg
}

// GetRegular returns the leaderboard tally for addr, if any.
func GetRegular(addr address) (posted, done int, tipsEarned int64, guestSigns int, ok bool) {
	v := regularsTree.Get(addr.String())
	if v == nil {
		return 0, 0, 0, 0, false
	}
	reg := v.(*Regular)
	return reg.QuestsPosted, reg.QuestsDone, reg.TipsEarned, reg.GuestSigns, true
}

// EscrowUgnot returns the total tips (in ugnot) currently locked in live
// quests. It always equals the sum of Tip over OPEN and CLAIMED quests.
func EscrowUgnot() int64 {
	return escrowUgnot
}

package tankardtales

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
	dave  = testutils.TestAddress("dave")
)

// expectPanic fails the test unless fn aborts with a message containing
// substr. The realm's public functions are entered via cross(cur), so
// their panics cross a realm boundary and surface as aborts — a plain
// recover() cannot catch them; uassert.AbortsContains wraps the VM's
// revive mechanism, which can.
func expectPanic(t *testing.T, rlm realm, substr string, fn func()) {
	t.Helper()
	uassert.AbortsContains(t, rlm, substr, fn)
}

func TestSignGuestbook(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))

	// Delta-based assertions: realm state may be shared across the
	// package's tests in one run, so never assume a blank tavern.
	_, _, signs0, _ := GetGuest(alice)
	_, _, _, guestSigns0, _ := GetRegular(alice)
	before := GuestCount()
	_, _, _, hadEntry := GetGuest(alice)

	SignGuestbook(cross(cur), "Alice", "First round is on me.")
	name, message, signs, ok := GetGuest(alice)
	uassert.Equal(t, ok, true)
	uassert.Equal(t, name, "Alice")
	uassert.Equal(t, message, "First round is on me.")
	uassert.Equal(t, signs, signs0+1)
	if !hadEntry {
		uassert.Equal(t, GuestCount(), before+1)
	}
	countAfterFirst := GuestCount()

	// Signing again updates the entry and counts a return visit,
	// but does not create a second guest.
	SignGuestbook(cross(cur), "Alice A.", "Back again!")
	name, message, signs, _ = GetGuest(alice)
	uassert.Equal(t, name, "Alice A.")
	uassert.Equal(t, message, "Back again!")
	uassert.Equal(t, signs, signs0+2)
	uassert.Equal(t, GuestCount(), countAfterFirst)

	// The regulars tally noticed both visits.
	_, _, _, guestSigns, ok := GetRegular(alice)
	uassert.Equal(t, ok, true)
	uassert.Equal(t, guestSigns, guestSigns0+2)
}

func TestGuestbookMultipleGuests(cur realm, t *testing.T) {
	before := GuestCount()

	testing.SetRealm(testing.NewUserRealm(bob))
	SignGuestbook(cross(cur), "Bob", "Questing for hire.")
	testing.SetRealm(testing.NewUserRealm(carol))
	SignGuestbook(cross(cur), "Carol", "Just here for the songs.")

	uassert.Equal(t, GuestCount(), before+2)

	_, msg, _, _ := GetGuest(bob)
	uassert.Equal(t, msg, "Questing for hire.")
	_, msg, _, _ = GetGuest(carol)
	uassert.Equal(t, msg, "Just here for the songs.")
}

func TestGuestbookRejectsBadInput(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(dave))

	expectPanic(t, cur, "display name must be 1-32 characters", func() {
		SignGuestbook(cross(cur), "  ", "hello")
	})
	expectPanic(t, cur, "display name must be 1-32 characters", func() {
		SignGuestbook(cross(cur), strings.Repeat("x", MaxNameLen+1), "hello")
	})
	expectPanic(t, cur, "message must be 1-280 characters", func() {
		SignGuestbook(cross(cur), "Dave", " ")
	})
	expectPanic(t, cur, "message must be 1-280 characters", func() {
		SignGuestbook(cross(cur), "Dave", strings.Repeat("x", MaxMessageLen+1))
	})

	// None of the failed attempts left a signature behind.
	_, _, _, ok := GetGuest(dave)
	uassert.Equal(t, ok, false)
}

// Package rosca is a dependency-free toolkit for building rotating savings
// and credit associations (ROSCA — "arisan", "tanda", "chit fund", "susus")
// on Gno.land.
//
// It contains no state and no realm capability of its own: the economics,
// the deterministic payout schedule and the presentation helpers are pure
// functions, so any realm can import this package and add a savings circle
// to its own state machine without re-deriving the hard parts.
//
// The companion realm gno.land/r/<addr>/kolektif is the reference
// implementation; it imports exactly these helpers.
package rosca

import (
	"crypto/sha256"
	"errors"
	"strconv"
	"strings"
)

// Status is the lifecycle stage of a circle.
type Status uint8

const (
	// StatusOpen collects members and collateral. Nothing is paid out.
	StatusOpen Status = iota
	// StatusActive is a full circle that is paying round by round.
	StatusActive
	// StatusComplete means every payout happened and collateral was returned.
	StatusComplete
)

// String renders a status as a short label.
func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "OPEN"
	case StatusActive:
		return "ACTIVE"
	case StatusComplete:
		return "COMPLETE"
	}
	return "UNKNOWN"
}

// Limits keep a circle inside numbers the reference realm can render and
// settle safely. They are advisory: an importing realm may enforce others.
const (
	MinSize          = 3
	MaxSize          = 50
	MinContribution  = int64(1000)         // 0.001 GNOT
	MaxContribution  = int64(100000000000) // 100,000 GNOT
	MinRoundSpan     = int64(60)           // 1 minute
	MaxRoundSpan     = int64(2592000)      // 30 days
	MaxNameLen       = 64
	DefaultRoundSpan = int64(604800) // 7 days
	UgnotPerGnot     = int64(1000000)
)

// Params is the immutable economics of a circle.
//
// Contribution is what each member pays every round. Collateral is what a
// member locks when joining; it is returned at completion and slashed into
// the penalty fund when the member defaults.
type Params struct {
	Contribution int64
	Collateral   int64
	Size         int
	RoundSpan    int64 // seconds per round
}

// Validate checks the parameters of a circle.
func (p Params) Validate() error {
	if p.Size < MinSize || p.Size > MaxSize {
		return errors.New("size must be between 3 and 50 members")
	}
	if p.Contribution < MinContribution || p.Contribution > MaxContribution {
		return errors.New("contribution out of range")
	}
	if p.Collateral != p.Contribution {
		return errors.New("collateral must equal one round contribution")
	}
	if p.RoundSpan < MinRoundSpan || p.RoundSpan > MaxRoundSpan {
		return errors.New("round span must be between 1 minute and 30 days")
	}
	return nil
}

// Pot is the payout one round produces when every seat pays.
func (p Params) Pot() int64 {
	return p.Contribution * int64(p.Size)
}

// Locked is the capital a circle needs at rest: every seat's collateral.
func (p Params) Locked() int64 {
	return p.Collateral * int64(p.Size)
}

// NetPerMember is the net cash flow of an ideal circle (no defaults) for a
// member who stays to the end: they pay Size contributions and receive one
// pot of Size contributions. It is always zero, which is the point of a
// ROSCA: it is a savings rotation, not a loan.
func (p Params) NetPerMember() int64 {
	return p.Pot() - p.Contribution*int64(p.Size)
}

// Seed builds the activation seed for a circle. Mixing the circle ID, the
// activation height and the sorted member set means the payout order cannot
// be chosen by the creator after the fact, and every node derives the same
// order from the same chain state.
func Seed(circleID uint64, height int64, members []string) string {
	parts := make([]string, len(members))
	copy(parts, members)
	sortStrings(parts)
	return strconv.FormatUint(circleID, 10) + "|" +
		strconv.FormatInt(height, 10) + "|" +
		strings.Join(parts, ",")
}

// Order returns a deterministic permutation of 0..n-1 derived from seed.
//
// It is a Fisher-Yates shuffle over bytes of SHA-256(seed:counter), so the
// same seed always yields the same order on every machine and every replay.
func Order(n int, seed string) []int {
	idx := make([]int, n)
	for i := 0; i < n; i++ {
		idx[i] = i
	}
	if n < 2 {
		return idx
	}
	p := newPRNG(seed)
	for i := n - 1; i > 0; i-- {
		j := int(p.next() % uint64(i+1))
		idx[i], idx[j] = idx[j], idx[i]
	}
	return idx
}

// Split divides amount into n shares. Any remainder goes one unit at a time
// to the first shares, so the shares always add up to amount exactly.
func Split(amount int64, n int) []int64 {
	out := make([]int64, n)
	if n <= 0 || amount <= 0 {
		return out
	}
	base := amount / int64(n)
	rem := amount % int64(n)
	for i := 0; i < n; i++ {
		out[i] = base
	}
	for i := 0; int64(i) < rem; i++ {
		out[i]++
	}
	return out
}

// Gnot formats a ugnot amount as GNOT with up to six decimals and no
// trailing zeros: 1500000 -> "1.5", 1000 -> "0.001".
func Gnot(ugnot int64) string {
	neg := ugnot < 0
	if neg {
		ugnot = -ugnot
	}
	whole := ugnot / UgnotPerGnot
	frac := ugnot % UgnotPerGnot
	s := strconv.FormatInt(whole, 10)
	if frac > 0 {
		f := strconv.FormatInt(frac+UgnotPerGnot, 10)[1:] // zero padded, 6 digits
		f = strings.TrimRight(f, "0")
		s += "." + f
	}
	if neg {
		s = "-" + s
	}
	return s
}

// HumanDuration renders a number of seconds as a compact human string:
// 90061 -> "1d 1h", 3600 -> "1h", 45 -> "45s".
func HumanDuration(seconds int64) string {
	if seconds <= 0 {
		return "now"
	}
	d := seconds / 86400
	h := (seconds % 86400) / 3600
	m := (seconds % 3600) / 60
	s := seconds % 60
	out := ""
	if d > 0 {
		out += strconv.FormatInt(d, 10) + "d "
	}
	if h > 0 && d < 100 {
		out += strconv.FormatInt(h, 10) + "h "
	}
	if m > 0 && d == 0 {
		out += strconv.FormatInt(m, 10) + "m "
	}
	if s > 0 && d == 0 && h == 0 {
		out += strconv.FormatInt(s, 10) + "s"
	}
	return strings.TrimSpace(out)
}

// Bar renders a fixed width progress bar in plain ASCII, so it survives every
// monospace font gnoweb may be served with: "[###---]".
func Bar(done, total, width int) string {
	if width <= 0 {
		return ""
	}
	if total <= 0 || done <= 0 {
		return "[" + strings.Repeat("-", width) + "]"
	}
	if done > total {
		done = total
	}
	filled := done * width / total
	if filled == 0 {
		filled = 1
	}
	if filled > width {
		filled = width
	}
	return "[" + strings.Repeat("#", filled) + strings.Repeat("-", width-filled) + "]"
}

// ShortAddr shortens a bech32 address for tables: g1abc…wxyz.
func ShortAddr(addr string) string {
	if len(addr) <= 14 {
		return addr
	}
	return addr[:7] + "…" + addr[len(addr)-4:]
}

// SortAddresses returns a sorted copy of the given addresses.
func SortAddresses(addrs []string) []string {
	out := make([]string, len(addrs))
	copy(out, addrs)
	sortStrings(out)
	return out
}

// --- internals ---------------------------------------------------------

// prng is a deterministic byte stream: SHA-256(seed:counter) concatenated.
type prng struct {
	seed string
	buf  []byte
	ctr  int
}

func newPRNG(seed string) *prng {
	return &prng{seed: seed}
}

func (p *prng) next() uint64 {
	for len(p.buf) < 8 {
		h := sha256.Sum256([]byte(p.seed + ":" + strconv.Itoa(p.ctr)))
		p.ctr++
		p.buf = append(p.buf, h[:]...)
	}
	b := p.buf[:8]
	p.buf = p.buf[8:]
	var v uint64
	for i := 0; i < 8; i++ {
		v = v<<8 | uint64(b[i])
	}
	return v
}

// sortStrings is a small insertion sort: member sets are tiny, and this keeps
// the package free of a sort import on every chain.
func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

package rosca

import (
	"strings"
	"testing"
)

func TestOrderIsDeterministic(t *testing.T) {
	seed := Seed(7, 123456, []string{"g1alice", "g1bob", "g1carol", "g1dave", "g1erin"})
	a := Order(5, seed)
	b := Order(5, seed)

	if len(a) != 5 || len(b) != 5 {
		t.Fatalf("expected 5 entries, got %d and %d", len(a), len(b))
	}
	for i := 0; i < 5; i++ {
		if a[i] != b[i] {
			t.Fatalf("order is not deterministic at %d: %d vs %d", i, a[i], b[i])
		}
	}
}

func TestOrderIsAPermutation(t *testing.T) {
	seed := Seed(1, 99, []string{"g1a", "g1b", "g1c", "g1d", "g1e", "g1f", "g1g", "g1h"})
	order := Order(8, seed)

	seen := make([]bool, 8)
	for _, idx := range order {
		if idx < 0 || idx >= 8 {
			t.Fatalf("index out of range: %d", idx)
		}
		if seen[idx] {
			t.Fatalf("duplicate index %d in %v", idx, order)
		}
		seen[idx] = true
	}
	for i, ok := range seen {
		if !ok {
			t.Fatalf("index %d missing from %v", i, order)
		}
	}
}

func TestOrderDependsOnSeed(t *testing.T) {
	// Two seeds that differ only by activation height must not collapse to the
	// same order for a sizeable roster: that is the property the whole
	// "nobody can pick the winner" claim rests on.
	members := []string{"g1a", "g1b", "g1c", "g1d", "g1e", "g1f", "g1g", "g1h", "g1i", "g1j"}
	s1 := Seed(3, 1000, members)
	s2 := Seed(3, 1001, members)
	o1 := Order(10, s1)
	o2 := Order(10, s2)

	same := true
	for i := 0; i < 10; i++ {
		if o1[i] != o2[i] {
			same = false
		}
	}
	if same {
		t.Fatalf("different seeds produced the same order")
	}
}

func TestSeedIgnoresMemberOrder(t *testing.T) {
	a := Seed(1, 5, []string{"g1b", "g1a", "g1c"})
	b := Seed(1, 5, []string{"g1c", "g1a", "g1b"})
	if a != b {
		t.Fatalf("seed should not depend on input order: %q vs %q", a, b)
	}
}

func TestSplitSumsExactly(t *testing.T) {
	cases := []struct {
		amount int64
		n      int
	}{
		{1000, 3},
		{1001, 3},
		{1, 4},
		{999999, 7},
		{0, 5},
	}
	for _, c := range cases {
		parts := Split(c.amount, c.n)
		if len(parts) != c.n {
			t.Fatalf("expected %d parts, got %d", c.n, len(parts))
		}
		sum := int64(0)
		for _, p := range parts {
			sum += p
		}
		if sum != c.amount {
			t.Fatalf("split of %d into %d gave %d", c.amount, c.n, sum)
		}
	}
}

func TestParamsValidate(t *testing.T) {
	good := Params{Contribution: 1000000, Collateral: 1000000, Size: 3, RoundSpan: 60}
	if err := good.Validate(); err != nil {
		t.Fatalf("valid params rejected: %v", err)
	}

	bad := []Params{
		{Contribution: 1000000, Collateral: 1000000, Size: 2, RoundSpan: 60},
		{Contribution: 1000000, Collateral: 1000000, Size: 51, RoundSpan: 60},
		{Contribution: 10, Collateral: 10, Size: 3, RoundSpan: 60},
		{Contribution: 1000000, Collateral: 2000000, Size: 3, RoundSpan: 60},
		{Contribution: 1000000, Collateral: 1000000, Size: 3, RoundSpan: 5},
		{Contribution: 1000000, Collateral: 1000000, Size: 3, RoundSpan: 99999999},
	}
	for i, p := range bad {
		if err := p.Validate(); err == nil {
			t.Fatalf("case %d: invalid params accepted", i)
		}
	}
}

func TestEconomicsBalance(t *testing.T) {
	p := Params{Contribution: 2000000, Collateral: 2000000, Size: 5, RoundSpan: 3600}
	if p.Pot() != 10000000 {
		t.Fatalf("pot should be 10 GNOT, got %d", p.Pot())
	}
	if p.Locked() != 10000000 {
		t.Fatalf("locked should be 10 GNOT, got %d", p.Locked())
	}
	if p.NetPerMember() != 0 {
		t.Fatalf("an ideal circle must net to zero per member, got %d", p.NetPerMember())
	}
}

func TestGnotFormatting(t *testing.T) {
	cases := []struct {
		in   int64
		want string
	}{
		{0, "0"},
		{1000, "0.001"},
		{1000000, "1"},
		{1500000, "1.5"},
		{1234567, "1.234567"},
		{1001000, "1.001"},
		{-2000000, "-2"},
	}
	for _, c := range cases {
		if got := Gnot(c.in); got != c.want {
			t.Fatalf("Gnot(%d) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestBarWidth(t *testing.T) {
	b := Bar(1, 4, 8)
	if len(b) != 10 {
		t.Fatalf("bar should be 10 chars incl. brackets, got %q", b)
	}
	if !strings.HasPrefix(b, "[#") {
		t.Fatalf("expected some fill, got %q", b)
	}
	if got := Bar(0, 4, 4); got != "[----]" {
		t.Fatalf("empty bar wrong: %q", got)
	}
	if got := Bar(4, 4, 4); got != "[####]" {
		t.Fatalf("full bar wrong: %q", got)
	}
}

func TestHumanDuration(t *testing.T) {
	cases := []struct {
		in   int64
		want string
	}{
		{45, "45s"},
		{60, "1m"},
		{3600, "1h"},
		{90061, "1d 1h"},
		{0, "now"},
	}
	for _, c := range cases {
		if got := HumanDuration(c.in); got != c.want {
			t.Fatalf("HumanDuration(%d) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestShortAddr(t *testing.T) {
	got := ShortAddr("g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2")
	if got != "g1udyt8…08w2" {
		t.Fatalf("short addr wrong: %q", got)
	}
	if ShortAddr("g1abc") != "g1abc" {
		t.Fatalf("short input should pass through")
	}
}

package kolektif

import (
	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif/rosca"
)

// This file is the read-only surface of the realm. Any other realm, indexer or
// client can call these without a transaction and without a realm capability,
// which is what makes a Kolektif circle composable: a DAO can require
// "member in good standing of circle #7" before letting an address vote.

// CircleCount returns how many circles have ever been opened.
func CircleCount() uint64 {
	return uint64(len(circles))
}

// CircleSummary reports the core facts of a circle. It returns zero values and
// status "UNKNOWN" for an id that does not exist.
func CircleSummary(id uint64) (name string, contribution int64, size int, round int, status string, pool int64) {
	if id == 0 || int(id) > len(circles) {
		return "", 0, 0, 0, "UNKNOWN", 0
	}
	c := circles[id-1]
	return c.Name, c.Params.Contribution, c.Params.Size, c.Round, c.Status.String(), c.Pool
}

// IsMember reports whether addr holds a seat in circle id.
func IsMember(id uint64, addr address) bool {
	if id == 0 || int(id) > len(circles) {
		return false
	}
	return circles[id-1].Member(addr) != nil
}

// Standing reports a member's record. It returns zero values for a non-member.
func Standing(id uint64, addr address) (roundsPaid int, defaulted bool, received bool, collateral int64) {
	if id == 0 || int(id) > len(circles) {
		return 0, false, false, 0
	}
	m := circles[id-1].Member(addr)
	if m == nil {
		return 0, false, false, 0
	}
	return m.RoundsPaid, m.Defaulted, m.Received, m.Collateral
}

// GlobalStats returns the number of circles, the ugnot currently escrowed by
// all of them, and the ugnot paid out since deployment.
func GlobalStats() (count int, active int, escrowed int64, paidOut int64) {
	count = len(circles)
	for _, c := range circles {
		if c.Status == rosca.StatusActive {
			active++
		}
		escrowed += c.Pool
		paidOut += c.PaidOutTotal
	}
	return count, active, escrowed, paidOut
}

package kolektif

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif/rosca"
)

// circles holds every circle ever created on this realm. A circle's ID is its
// 1-based position, so circles[id-1] is the circle with that ID.
var (
	circles []*Circle
	seq     uint64
)

// Create opens a new circle. The caller becomes its creator but not a member:
// joining is a separate transaction because it locks collateral.
//
// contribution is denominated in ugnot (1 GNOT = 1000000 ugnot); collateral is
// always one contribution; roundSpan is the length of a round in seconds.
func Create(cur realm, name string, contribution int64, size int, roundSpan int64) uint64 {
	caller := cur.Previous().Address()
	// Opening a circle is free. Reading the envelope makes the VM's
	// "coins were sent but never read" rule explicit here: a stray payment
	// reverts the whole transaction instead of getting stuck in the realm.
	if sent := unsafe.OriginSend(); sent.AmountOf("ugnot") > 0 {
		panic("kolektif: opening a circle is free, do not attach coins")
	}
	name = strings.TrimSpace(name)
	if len(name) < 3 {
		panic("kolektif: name needs at least 3 characters")
	}
	if len(name) > rosca.MaxNameLen {
		panic("kolektif: name is longer than 64 characters")
	}
	params := rosca.Params{
		Contribution: contribution,
		Collateral:   contribution,
		Size:         size,
		RoundSpan:    roundSpan,
	}
	if err := params.Validate(); err != nil {
		panic("kolektif: " + err.Error())
	}

	seq++
	c := &Circle{
		ID:        seq,
		Name:      name,
		Creator:   caller,
		Params:    params,
		Status:    rosca.StatusOpen,
		OpenedAt: time.Now(),
	}
	circles = append(circles, c)

	chain.Emit("CircleCreated",
		"id", strconv.FormatUint(c.ID, 10),
		"creator", caller.String(),
		"contribution", strconv.FormatInt(contribution, 10),
		"size", strconv.Itoa(size),
	)
	return c.ID
}

// Join takes a seat in an open circle and locks exactly one contribution as
// collateral. When the last seat fills, the circle activates: the payout order
// is fixed from chain state and round 1 opens.
func Join(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusOpen {
		panic("kolektif: this circle is no longer open")
	}
	caller := cur.Previous().Address()
	if c.Member(caller) != nil {
		panic("kolektif: you already hold a seat in this circle")
	}
	if len(c.Members) >= c.Params.Size {
		panic("kolektif: this circle is full")
	}
	requireExact(cur, c.Params.Collateral, "collateral")

	c.Members = append(c.Members, &Member{
		Addr:       caller,
		Collateral: c.Params.Collateral,
		PaidRound:  -1,
		JoinedAt:   time.Now(),
	})
	c.Pool += c.Params.Collateral

	chain.Emit("MemberJoined",
		"id", strconv.FormatUint(c.ID, 10),
		"member", caller.String(),
		"seats", strconv.Itoa(len(c.Members)),
	)

	if len(c.Members) >= c.Params.Size {
		activate(c)
	}
}

// Contribute pays one round for the caller. When the last active member pays,
// the pot is released to the round's beneficiary in the same transaction.
func Contribute(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusActive {
		panic("kolektif: this circle is not active")
	}
	caller := cur.Previous().Address()
	m := c.Member(caller)
	if m == nil {
		panic("kolektif: you do not hold a seat in this circle")
	}
	if m.Defaulted {
		panic("kolektif: you defaulted earlier in this circle")
	}
	if m.PaidRound >= c.Round {
		panic("kolektif: you already paid round " + strconv.Itoa(c.Round))
	}
	if time.Now().Unix() > c.Deadline.Unix() {
		panic("kolektif: the round deadline passed; call Advance to settle defaults first")
	}
	requireExact(cur, c.Params.Contribution, "round contribution")

	m.PaidRound = c.Round
	m.RoundsPaid++
	c.Pool += c.Params.Contribution
	c.PaidInTotal += c.Params.Contribution

	chain.Emit("Contribution",
		"id", strconv.FormatUint(c.ID, 10),
		"member", caller.String(),
		"round", strconv.Itoa(c.Round),
		"amount", strconv.FormatInt(c.Params.Contribution, 10),
	)

	if c.RoundPaid() {
		settle(cur, c)
	}
}

// Advance settles a round whose deadline passed. Every active member that did
// not pay is declared in default: their collateral moves to the penalty fund
// that honest members share when the circle closes, they lose the seat, and
// the round's pot is released from whatever was actually collected.
//
// Anyone can call this: it is not a privilege, it is cleanup.
func Advance(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusActive {
		panic("kolektif: this circle is not active")
	}
	if c.RoundPaid() {
		panic("kolektif: every active member already paid this round")
	}
	if time.Now().Unix() <= c.Deadline.Unix() {
		panic("kolektif: the round deadline has not passed yet")
	}

	defaulted := 0
	for _, m := range c.Members {
		if m.Defaulted || m.PaidRound >= c.Round {
			continue
		}
		m.Defaulted = true
		defaulted++
		if m.Collateral > 0 {
			c.Penalty += m.Collateral
			c.Payouts = append(c.Payouts, Payout{
				Round:  c.Round,
				To:     m.Addr,
				Amount: m.Collateral,
				At:     time.Now(),
				Kind:   "slash",
			})
			m.Collateral = 0
		}
	}
	if defaulted == 0 {
		panic("kolektif: nothing to settle")
	}

	chain.Emit("DefaultsDeclared",
		"id", strconv.FormatUint(c.ID, 10),
		"round", strconv.Itoa(c.Round),
		"count", strconv.Itoa(defaulted),
	)

	settle(cur, c)
}

// Leave returns the caller's collateral and frees the seat. Only possible
// while the circle is still open: once it is active the round schedule is
// committed, and leaving is handled as a default instead.
func Leave(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusOpen {
		panic("kolektif: you can only leave a circle that has not been activated")
	}
	caller := cur.Previous().Address()
	for i, m := range c.Members {
		if m.Addr != caller {
			continue
		}
		sendUgnot(cur, c, m.Addr, m.Collateral)
		m.Collateral = 0
		c.Members = append(c.Members[:i], c.Members[i+1:]...)
		chain.Emit("MemberLeft", "id", strconv.FormatUint(c.ID, 10), "member", caller.String())
		return
	}
	panic("kolektif: you do not hold a seat in this circle")
}

// Cancel closes a circle that never filled and refunds every seat. Only the
// creator can cancel.
func Cancel(cur realm, id uint64) {
	c := mustCircle(id)
	if cur.Previous().Address() != c.Creator {
		panic("kolektif: only the creator can cancel a circle")
	}
	if c.Status != rosca.StatusOpen {
		panic("kolektif: only an open circle can be cancelled")
	}
	for _, m := range c.Members {
		if m.Collateral > 0 {
			sendUgnot(cur, c, m.Addr, m.Collateral)
			c.Payouts = append(c.Payouts, Payout{
				Round:  -1,
				To:     m.Addr,
				Amount: m.Collateral,
				At:     time.Now(),
				Kind:   "refund",
			})
			m.Collateral = 0
		}
	}
	c.Status = rosca.StatusComplete
	c.Cancelled = true
	c.ClosedAt = time.Now()
	chain.Emit("CircleCancelled", "id", strconv.FormatUint(c.ID, 10))
}

// --- internal state machine -------------------------------------------

// activate turns a full circle into a running one and fixes its payout order.
func activate(c *Circle) {
	parts := make([]string, 0, len(c.Members))
	for _, m := range c.Members {
		parts = append(parts, m.Addr.String())
	}
	height := runtime.ChainHeight()
	c.Seed = rosca.Seed(c.ID, height, parts)
	c.Order = rosca.Order(len(c.Members), c.Seed)
	c.ActivateHeight = height
	c.Status = rosca.StatusActive
	c.ActivatedAt = time.Now()
	c.Round = 0
	c.Deadline = c.ActivatedAt.Add(time.Duration(c.Params.RoundSpan) * time.Second)

	chain.Emit("CircleActivated",
		"id", strconv.FormatUint(c.ID, 10),
		"height", strconv.FormatInt(height, 10),
		"seed", c.Seed,
	)
}

// settle pays the current round's pot to the next beneficiary, then either
// opens the next round or closes the circle.
func settle(cur realm, c *Circle) {
	pot := int64(0)
	for _, m := range c.Members {
		if !m.Defaulted && m.PaidRound == c.Round {
			pot += c.Params.Contribution
		}
	}
	bi := c.NextBeneficiary()
	if bi < 0 || pot <= 0 {
		finish(cur, c)
		return
	}

	ben := c.Members[bi]
	sendUgnot(cur, c, ben.Addr, pot)
	ben.Received = true
	c.Payouts = append(c.Payouts, Payout{
		Round:  c.Round,
		To:     ben.Addr,
		Amount: pot,
		At:     time.Now(),
		Kind:   "pot",
	})

	chain.Emit("PotPaid",
		"id", strconv.FormatUint(c.ID, 10),
		"round", strconv.Itoa(c.Round),
		"to", ben.Addr.String(),
		"amount", strconv.FormatInt(pot, 10),
	)

	c.Round++
	if c.RoundsSettled() >= c.RoundsPlanned() {
		finish(cur, c)
		return
	}
	c.Deadline = time.Now().Add(time.Duration(c.Params.RoundSpan) * time.Second)
}

// finish closes the circle: every honest member gets their collateral back
// plus an equal share of the slashed penalty fund.
func finish(cur realm, c *Circle) {
	honest := make([]*Member, 0, len(c.Members))
	for _, m := range c.Members {
		if !m.Defaulted {
			honest = append(honest, m)
		}
	}
	shares := rosca.Split(c.Penalty, len(honest))
	for i, m := range honest {
		amount := m.Collateral + shares[i]
		if amount <= 0 {
			continue
		}
		sendUgnot(cur, c, m.Addr, amount)
		c.Payouts = append(c.Payouts, Payout{
			Round:  -1,
			To:     m.Addr,
			Amount: amount,
			At:     time.Now(),
			Kind:   "refund",
		})
		m.Collateral = 0
	}
	c.Penalty = 0
	c.Status = rosca.StatusComplete
	c.ClosedAt = time.Now()

	chain.Emit("CircleClosed",
		"id", strconv.FormatUint(c.ID, 10),
		"paidOut", strconv.FormatInt(c.PaidOutTotal, 10),
	)
}

// --- money helpers -----------------------------------------------------

// requireExact asserts that the transaction carried exactly want ugnot.
//
// Only user transactions are accepted: OriginSend() describes the coins that
// landed on this realm for a MsgCall, and a realm-to-realm call would make that
// number mean something else.
func requireExact(cur realm, want int64, what string) {
	prev := cur.Previous()
	// A real payment arrives with a user realm on the stack (MsgCall). Calls
	// from another package are refused: OriginSend() describes coins that landed
	// on *this* realm only when the caller is a plain user transaction. A call
	// from our own package is the unit-test harness inside the realm itself.
	if !prev.IsUser() && prev.PkgPath() != cur.PkgPath() {
		panic("kolektif: only direct user transactions can move funds")
	}
	got := unsafe.OriginSend().AmountOf("ugnot")
	if got != want {
		panic("kolektif: " + what + " must be exactly " + rosca.Gnot(want) + " GNOT, received " + rosca.Gnot(got))
	}
}

// sendUgnot pays amount out of the circle's pool.
func sendUgnot(cur realm, c *Circle, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if amount > c.Pool {
		panic("kolektif: accounting invariant violated: payout exceeds circle pool")
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
	c.Pool -= amount
	c.PaidOutTotal += amount
}

func mustCircle(id uint64) *Circle {
	if id == 0 || int(id) > len(circles) {
		panic("kolektif: unknown circle id")
	}
	return circles[id-1]
}

package kolektif

import (
	"strings"
	"testing"

	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif/rosca"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// newFilledCircle creates a circle and seats three members, which activates it.
//
// testing.SetRealm only applies to the frame that calls it, so every seat is
// taken inline here rather than through a shared helper.
func newFilledCircle(cur realm, t *testing.T, contribution int64, span int64) uint64 {
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")
	carol := testutils.TestAddress("carol")

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Create(cross(cur), "Warung Crew", contribution, 3, span)
	if id != 1 {
		t.Fatalf("expected the first circle to be id 1, got %d", id)
	}

	members := []address{alice, bob, carol}
	for _, m := range members {
		testing.SetRealm(testing.NewUserRealm(m))
		payFrom(contribution)
		Join(cross(cur), id)
	}
	return id
}

func TestNoDefaultsEveryMemberNetsZero(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")
	carol := testutils.TestAddress("carol")
	members := []address{alice, bob, carol}

	start := int64(10) * gnot
	for _, m := range members {
		fund(m, start)
	}

	id := newFilledCircle(cross(cur), t, 1*gnot, 60)
	c := mustCircle(id)

	if c.Status != rosca.StatusActive {
		t.Fatalf("circle should be active after the last seat fills, got %s", c.Status.String())
	}
	if len(c.Order) != 3 {
		t.Fatalf("expected an order of 3, got %d", len(c.Order))
	}
	if c.Pool != 3*gnot {
		t.Fatalf("pool should hold 3 GNOT of collateral, got %d", c.Pool)
	}

	// Three rounds: everyone pays, the last payer releases the pot.
	sent := make(map[address]int64, 3)
	for round := 0; round < 3; round++ {
		for _, m := range members {
			testing.SetRealm(testing.NewUserRealm(m))
			payFrom(1 * gnot)
			Contribute(cross(cur), id)
			sent[m] = sent[m] + 1*gnot
		}
	}
	// The collateral locked at join counts as sent too.
	for _, m := range members {
		sent[m] = sent[m] + 1*gnot
	}

	c = mustCircle(id)
	if c.Status != rosca.StatusComplete {
		t.Fatalf("circle should be complete, got %s", c.Status.String())
	}
	if c.Pool != 0 {
		t.Fatalf("circle pool should be empty at close, got %d", c.Pool)
	}

	// No defaults: what every member received back equals what they paid in.
	// The test harness credits the realm without debiting the member, so the
	// member's balance only moves on payouts: received == balance - funded.
	for _, m := range members {
		received := balanceOf(m) - start
		if received != sent[m] {
			t.Fatalf("member %s should net zero: paid %d, received %d",
				m.String(), sent[m], received)
		}
	}
	if balanceOf(realmAddr) != 0 {
		t.Fatalf("realm should hold nothing after close, holds %d", balanceOf(realmAddr))
	}
	if c.PaidOutTotal != 12*gnot {
		t.Fatalf("expected 12 GNOT paid out (9 in pots + 3 collateral), got %d", c.PaidOutTotal)
	}
	for _, m := range c.Members {
		if !m.Received {
			t.Fatalf("member %s never received the pot", m.Addr.String())
		}
	}
}

func TestDefaultIsSlashedAndRedistributed(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")
	carol := testutils.TestAddress("carol")

	start := int64(10) * gnot
	fund(alice, start)
	fund(bob, start)
	fund(carol, start)

	id := newFilledCircle(cross(cur), t, 1*gnot, 60)
	c := mustCircle(id)

	// Round 0: alice and bob pay, carol does not.
	testing.SetRealm(testing.NewUserRealm(alice))
	payFrom(1 * gnot)
	Contribute(cross(cur), id)

	testing.SetRealm(testing.NewUserRealm(bob))
	payFrom(1 * gnot)
	Contribute(cross(cur), id)

	// Let the round deadline pass: SkipHeights moves block time by 5s per block.
	testing.SkipHeights(30)

	testing.SetRealm(testing.NewUserRealm(alice))
	Advance(cross(cur), id)

	c = mustCircle(id)
	carolSeat := c.Member(carol)
	if carolSeat == nil {
		t.Fatalf("carol should stay on the roster, marked defaulted")
	}
	if !carolSeat.Defaulted {
		t.Fatalf("carol should be in default")
	}
	if carolSeat.Collateral != 0 {
		t.Fatalf("defaulted collateral should be slashed, got %d", carolSeat.Collateral)
	}
	if carolSeat.Received {
		t.Fatalf("a defaulted member must not receive a pot")
	}

	// The two honest members keep paying until both have received.
	guard := 0
	for mustCircle(id).Status == rosca.StatusActive {
		guard++
		if guard > 10 {
			t.Fatalf("circle did not close after the default")
		}
		testing.SetRealm(testing.NewUserRealm(alice))
		payFrom(1 * gnot)
		Contribute(cross(cur), id)
		testing.SetRealm(testing.NewUserRealm(bob))
		payFrom(1 * gnot)
		Contribute(cross(cur), id)
	}

	c = mustCircle(id)
	if c.Status != rosca.StatusComplete {
		t.Fatalf("circle should close, got %s", c.Status.String())
	}
	if got := balanceOf(realmAddr); got != 0 {
		t.Fatalf("realm should hold nothing, holds %d", got)
	}
	if got := balanceOf(carol) - start; got != 0 {
		t.Fatalf("carol should receive nothing back, got %d", got)
	}
	if got := balanceOf(alice) - start; got != 2*gnot+gnot+gnot/2 {
		t.Fatalf("alice should get one pot, her collateral and half the penalty = 3.5 GNOT, got %d", got)
	}
	if got := balanceOf(bob) - start; got != 2*gnot+gnot+gnot/2 {
		t.Fatalf("bob should get one pot, his collateral and half the penalty = 3.5 GNOT, got %d", got)
	}
}
