	testing.SetRealm(testing.NewUserRealm(bob))
	payFrom(1 * gnot)
	Join(cross(cur), id)

	testing.SetRealm(testing.NewUserRealm(alice))
	Cancel(cross(cur), id)

	c := mustCircle(id)
	if got := balanceOf(alice) - 5*gnot; got != 1*gnot {
