// Package puzzlerounds is the reusable, stateless puzzle-round library
// behind Riddle Tavern (gno.land/r/g1j7l6ekxy82r9tav7d8jv3gp0h3xaunw2m2k3lx/riddletavern).
//
// It holds the commitment scheme, the round record, streak math and
// leaderboard ordering, so any other realm or package can import it and run
// the same twice-daily puzzle game without copying the logic.
//
// Answer commitment scheme (public, part of the game rules):
//   - An answer is an integer. It is encoded as its decimal string
//     (strconv.Itoa) and committed with sha256.
//   - Only the hash is ever stored on-chain; the answer itself is never
//     stored. Anyone can recompute HashAnswer to verify a round.
//   - Note the honest limitation, shared with the BSC original this ports
//     (Puzzle Arena, which used keccak256 the same way): small-integer
//     answers are brute-forceable from the hash in principle. The hash is
//     a commitment that the round cannot be changed after creation, not
//     a vault. The game is the puzzle, the live window and one entry per
//     player — not the secrecy of the answer.
package puzzlerounds

import (
	"crypto/sha256"
	"strconv"
)

// AnswerHash is a sha256 commitment to a puzzle answer.
type AnswerHash [32]byte

// HashAnswer computes the commitment for an answer.
//
// The answer is encoded as its decimal string and hashed with sha256.
// The encoding is part of the public commitment scheme: anyone can
// recompute it to verify a round, and the answer itself is never stored.
func HashAnswer(answer int) AnswerHash {
	return sha256.Sum256([]byte(strconv.Itoa(answer)))
}

// VerifyAnswer reports whether answer matches the stored commitment.
func VerifyAnswer(hash AnswerHash, answer int) bool {
	return HashAnswer(answer) == hash
}

// Round is the public record of one puzzle round. It carries no behaviour
// of its own; the realm that owns the round holds the state.
type Round struct {
	Question   string     // puzzle text, shown to players
	AnswerHash AnswerHash // sha256(decimal answer); the answer is never stored
	Start      int64      // unix seconds, inclusive
	End        int64      // unix seconds, inclusive
	Solves     int        // correct solves so far
}

// IsOpen reports whether unix time now falls inside the round window.
func (r Round) IsOpen(now int64) bool {
	return now >= r.Start && now <= r.End
}

// DayOf returns the UTC day number for a unix timestamp.
func DayOf(unix int64) int64 {
	return unix / 86400
}

// NextStreak computes the new streak after a solve on day today,
// given the day of the previous solve (lastDay, 0 if never) and the
// current streak. Ported from Puzzle Arena (BSC):
//   - a second solve on the same day leaves the streak unchanged
//     (two rounds run per day, so a same-day solve must not reset it),
//   - a solve the day after the last one extends the streak by one,
//   - anything else restarts the streak at 1.
func NextStreak(lastDay int64, streak int, today int64) int {
	if today > 0 && lastDay == today {
		return streak
	}
	if today > 0 && lastDay == today-1 {
		return streak + 1
	}
	return 1
}

// Leader is one row of the leaderboard.
type Leader struct {
	Solver address
	Solves int
	Streak int
}

// SortLeaders sorts in place: most solves first, then highest streak,
// then lowest address (deterministic tie-break).
func SortLeaders(leaders []Leader) {
	// Insertion sort: leaderboards are small, and sort.Slice is not
	// available in Gno.
	for i := 1; i < len(leaders); i++ {
		for j := i; j > 0 && lessLeader(leaders[j], leaders[j-1]); j-- {
			leaders[j], leaders[j-1] = leaders[j-1], leaders[j]
		}
	}
}

func lessLeader(a, b Leader) bool {
	if a.Solves != b.Solves {
		return a.Solves > b.Solves
	}
	if a.Streak != b.Streak {
		return a.Streak > b.Streak
	}
	return a.Solver.String() < b.Solver.String()
}

package puzzlerounds

import (
	"encoding/hex"
	"testing"
)

// mustHash decodes a known sha256 hex vector (computed offline, independent
// of HashAnswer) so the test checks the implementation, not itself.
func mustHash(t *testing.T, hexStr string) AnswerHash {
	t.Helper()
	b, err := hex.DecodeString(hexStr)
	if err != nil {
		t.Fatalf("bad test vector: %v", err)
	}
	var h AnswerHash
	copy(h[:], b)
	return h
}

func TestHashAnswer(t *testing.T) {
	// sha256("42") = 73475cb40a568e8da8a045ced110137e159f890ac4da883b6b17dc651b3a8049
	want := mustHash(t, "73475cb40a568e8da8a045ced110137e159f890ac4da883b6b17dc651b3a8049")
	if got := HashAnswer(42); got != want {
		t.Fatalf("HashAnswer(42) = %x, want %x", got, want)
	}
	// sha256("0") = 5feceb66ffc86f38d952786c6d696c79c2dbc239dd4e91b46729d73a27fb57e9
	want0 := mustHash(t, "5feceb66ffc86f38d952786c6d696c79c2dbc239dd4e91b46729d73a27fb57e9")
	if got := HashAnswer(0); got != want0 {
		t.Fatalf("HashAnswer(0) = %x, want %x", got, want0)
	}
}

func TestVerifyAnswer(t *testing.T) {
	h := HashAnswer(2520)
	if !VerifyAnswer(h, 2520) {
		t.Fatalf("VerifyAnswer: correct answer rejected")
	}
	if VerifyAnswer(h, 2521) {
		t.Fatalf("VerifyAnswer: wrong answer accepted")
	}
	if VerifyAnswer(h, 0) {
		t.Fatalf("VerifyAnswer: zero answer accepted")
	}
}

func TestRoundIsOpen(t *testing.T) {
	r := Round{Start: 1000, End: 2000}
	if r.IsOpen(999) {
		t.Fatalf("round open before start")
	}
	if !r.IsOpen(1000) {
		t.Fatalf("round closed at start (inclusive)")
	}
	if !r.IsOpen(1500) {
		t.Fatalf("round closed mid-window")
	}
	if !r.IsOpen(2000) {
		t.Fatalf("round closed at end (inclusive)")
	}
	if r.IsOpen(2001) {
		t.Fatalf("round open after end")
	}
}

func TestDayOf(t *testing.T) {
	if DayOf(0) != 0 {
		t.Fatalf("DayOf(0) = %d, want 0", DayOf(0))
	}
	if DayOf(86399) != 0 {
		t.Fatalf("DayOf(86399) = %d, want 0", DayOf(86399))
	}
	if DayOf(86400) != 1 {
		t.Fatalf("DayOf(86400) = %d, want 1", DayOf(86400))
	}
	// The test VM's fixed time: 1234567890 / 86400 = 14288.
	if DayOf(1234567890) != 14288 {
		t.Fatalf("DayOf(1234567890) = %d, want 14288", DayOf(1234567890))
	}
}

func TestNextStreak(t *testing.T) {
	// First solve ever starts a streak of 1.
	if got := NextStreak(0, 0, 100); got != 1 {
		t.Fatalf("first solve: got %d, want 1", got)
	}
	// Solve the day after the last one extends the streak.
	if got := NextStreak(100, 3, 101); got != 4 {
		t.Fatalf("next-day solve: got %d, want 4", got)
	}
	// A second solve on the same day leaves the streak unchanged.
	if got := NextStreak(100, 3, 100); got != 3 {
		t.Fatalf("same-day solve: got %d, want 3", got)
	}
	// A gap of two or more days restarts the streak.
	if got := NextStreak(100, 5, 102); got != 1 {
		t.Fatalf("gap solve: got %d, want 1", got)
	}
	if got := NextStreak(100, 5, 200); got != 1 {
		t.Fatalf("long-gap solve: got %d, want 1", got)
	}
}

func TestSortLeaders(t *testing.T) {
	a := address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")
	b := address("g1skl80cuz8zq3lul9pgz5pc35l2pfzgxgfpsqkx")
	c := address("g1xrcglralkd8zaww0dn3q6qerh2xzq68h86z5r4")
	leaders := []Leader{
		{Solver: a, Solves: 2, Streak: 1},
		{Solver: b, Solves: 5, Streak: 2},
		{Solver: c, Solves: 5, Streak: 4},
	}
	SortLeaders(leaders)
	// c first: 5 solves, higher streak than b. b second. a last.
	if leaders[0].Solver != c || leaders[1].Solver != b || leaders[2].Solver != a {
		t.Fatalf("wrong order: %v %v %v", leaders[0].Solver, leaders[1].Solver, leaders[2].Solver)
	}

	// Tie on solves and streak: lowest address first.
	tied := []Leader{
		{Solver: b, Solves: 1, Streak: 1},
		{Solver: a, Solves: 1, Streak: 1},
	}
	SortLeaders(tied)
	if tied[0].Solver != a || tied[1].Solver != b {
		t.Fatalf("tie-break wrong: %v %v", tied[0].Solver, tied[1].Solver)
	}
}

// Package riddletavern is Riddle Tavern: twice-daily puzzle rounds on
// Gno.land, a port of Puzzle Arena (BSC, 598 solves) to Gno.
//
// How it works:
//   - The owner (the deployer) creates rounds with CreateRound, committing
//     to the answer by its sha256 hash only — the answer itself is never
//     stored on-chain. See gno.land/p/g1j7l6ekxy82r9tav7d8jv3gp0h3xaunw2m2k3lx/puzzlerounds for the commitment
//     scheme.
//   - Anyone can Solve a round while its window is open by submitting the
//     answer. A correct answer counts once per address per round, updates
//     the solver's streak (same-day solves don't reset it, a next-day
//     solve extends it, a gap restarts it) and the leaderboard.
//   - gnoweb renders the current round, its puzzle and the leaderboard via
//     Render().
//
// There is no fee, no payment and no token: solving is free, the game is
// the puzzle. The realm holds no funds and has no withdraw function.
package riddletavern

import (
	"chain"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1j7l6ekxy82r9tav7d8jv3gp0h3xaunw2m2k3lx/puzzlerounds"
)

var (
	owner       address
	roundCount  int
	totalSolves int

	rounds    map[int]puzzlerounds.Round
	solved    map[int]map[address]bool // roundID -> solver -> solved?
	solvesOf  map[address]int
	streakOf  map[address]int
	lastDayOf map[address]int64
	seen      map[address]bool // solvers seen, for leaderboard iteration
	solvers   []address
)

func init(cur realm) {
	// The deployer becomes the owner. Inside init(), PreviousRealm is the
	// deployer; after this the deployer is no longer available, so the
	// address is saved here. (In `gno test` there is no deployer and the
	// owner is empty; tests set it explicitly.)
	owner = cur.Previous().Address()
	rounds = make(map[int]puzzlerounds.Round)
	solved = make(map[int]map[address]bool)
	solvesOf = make(map[address]int)
	streakOf = make(map[address]int)
	lastDayOf = make(map[address]int64)
	seen = make(map[address]bool)
}

// Owner returns the address that may create rounds and transfer ownership.
func Owner() address {
	return owner
}

// TransferOwnership moves round creation to newOwner. Only the owner.
func TransferOwnership(cur realm, newOwner address) {
	caller := cur.Previous().Address()
	if caller != owner {
		panic("riddletavern: only owner can transfer ownership")
	}
	if !newOwner.IsValid() {
		panic("riddletavern: invalid address")
	}
	prev := owner
	owner = newOwner
	chain.Emit("OwnershipTransfer", "from", prev.String(), "to", newOwner.String())
}

// CreateRound schedules a new puzzle round. Only the owner. The answer is
// committed by hash: answerHashHex is the 64-character lowercase hex of
// sha256(decimal answer) — see puzzlerounds.HashAnswer — with an optional
// "0x" prefix, as in the seed file and the BSC original. start/end are
// unix seconds; start must not be in the past.
func CreateRound(cur realm, question string, answerHashHex string, start, end int64) int {
	caller := cur.Previous().Address()
	if caller != owner {
		panic("riddletavern: only owner can create rounds")
	}
	if question == "" {
		panic("riddletavern: empty question")
	}
	answerHashHex = strings.TrimPrefix(answerHashHex, "0x")
	hashBytes, err := hex.DecodeString(answerHashHex)
	if err != nil || len(hashBytes) != 32 {
		panic("riddletavern: answer hash must be 64 hex characters")
	}
	var answerHash puzzlerounds.AnswerHash
	copy(answerHash[:], hashBytes)
	if end <= start {
		panic("riddletavern: end must be after start")
	}
	if start < time.Now().Unix() {
		panic("riddletavern: start in the past")
	}
	roundCount++
	rounds[roundCount] = puzzlerounds.Round{
		Question:   question,
		AnswerHash: answerHash,
		Start:      start,
		End:        end,
	}
	chain.Emit("RoundCreated", "round", strconv.Itoa(roundCount), "start", strconv.FormatInt(start, 10), "end", strconv.FormatInt(end, 10))
	return roundCount
}

// Solve submits an answer for a round. The round must be open, the answer
// must match the committed hash, and the caller must not have solved this
// round before. One entry per address per round.
func Solve(cur realm, roundID int, answer int) {
	caller := cur.Previous().Address()
	round, ok := rounds[roundID]
	if !ok {
		panic("riddletavern: invalid round")
	}
	now := time.Now().Unix()
	if !round.IsOpen(now) {
		panic("riddletavern: round not open")
	}
	if !puzzlerounds.VerifyAnswer(round.AnswerHash, answer) {
		panic("riddletavern: wrong answer")
	}
	if solved[roundID] == nil {
		solved[roundID] = make(map[address]bool)
	}
	if solved[roundID][caller] {
		panic("riddletavern: already solved")
	}
	solved[roundID][caller] = true

	day := puzzlerounds.DayOf(now)
	streak := puzzlerounds.NextStreak(lastDayOf[caller], streakOf[caller], day)
	streakOf[caller] = streak
	lastDayOf[caller] = day

	if !seen[caller] {
		seen[caller] = true
		solvers = append(solvers, caller)
	}
	solvesOf[caller]++
	round.Solves++
	rounds[roundID] = round
	totalSolves++

	chain.Emit("Solved", "round", strconv.Itoa(roundID), "solver", caller.String(), "streak", strconv.Itoa(streak))
}

// RoundCount returns the number of rounds created so far (round IDs start at 1).
func RoundCount() int {
	return roundCount
}

// TotalSolves returns the number of correct solves across all rounds.
func TotalSolves() int {
	return totalSolves
}

// GetRound returns the round record and whether the round exists.
func GetRound(roundID int) (puzzlerounds.Round, bool) {
	round, ok := rounds[roundID]
	return round, ok
}

// SolvesOf returns a solver's lifetime correct-solve count.
func SolvesOf(solver address) int {
	return solvesOf[solver]
}

// StreakOf returns a solver's current streak in days.
func StreakOf(solver address) int {
	return streakOf[solver]
}

// SolvedBy reports whether solver already solved roundID.
func SolvedBy(roundID int, solver address) bool {
	if solved[roundID] == nil {
		return false
	}
	return solved[roundID][solver]
}

// Leaderboard returns all solvers ordered by solves (desc), then streak
// (desc), then address (asc). Empty when nobody has solved yet.
func Leaderboard() []puzzlerounds.Leader {
	leaders := make([]puzzlerounds.Leader, 0, len(solvers))
	for _, solver := range solvers {
		leaders = append(leaders, puzzlerounds.Leader{
			Solver: solver,
			Solves: solvesOf[solver],
			Streak: streakOf[solver],
		})
	}
	puzzlerounds.SortLeaders(leaders)
	return leaders
}

// Render shows the current round, its puzzle and the leaderboard in gnoweb.
// Render("/<roundID>") shows a specific round; any other path shows the
// latest round.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Riddle Tavern\n\n")
	b.WriteString("Twice-daily puzzles, verified on-chain. One entry per player per round — solve it, grow your streak, top the board.\n\n")
	b.WriteString("Rounds: " + strconv.Itoa(roundCount) + " · Total solves: " + strconv.Itoa(totalSolves) + "\n\n")

	roundID := roundCount
	if path != "" && path != "/" {
		if n, err := strconv.Atoi(strings.TrimPrefix(path, "/")); err == nil && n >= 1 && n <= roundCount {
			roundID = n
		}
	}
	if roundID < 1 {
		b.WriteString("No rounds yet — check back soon.\n")
	} else {
		round, _ := rounds[roundID]
		now := time.Now().Unix()
		status := "open"
		if now < round.Start {
			status = "not yet open"
		} else if now > round.End {
			status = "sealed"
		}
		b.WriteString("## Round " + strconv.Itoa(roundID) + " (" + status + ")\n\n")
		b.WriteString("**Puzzle:** " + round.Question + "\n\n")
		b.WriteString("Window: " + formatTime(round.Start) + " – " + formatTime(round.End) + " · Solves: " + strconv.Itoa(round.Solves) + "\n\n")
	}

	b.WriteString("## Leaderboard\n\n")
	leaders := Leaderboard()
	if len(leaders) == 0 {
		b.WriteString("No solvers yet — be the first.\n")
	} else {
		top := len(leaders)
		if top > 10 {
			top = 10
		}
		for i := 0; i < top; i++ {
			b.WriteString(strconv.Itoa(i+1) + ". " + leaders[i].Solver.String() + " — " + strconv.Itoa(leaders[i].Solves) + " solves, streak " + strconv.Itoa(leaders[i].Streak) + "\n")
		}
	}
	return b.String()
}

func formatTime(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04")
}

package riddletavern

import (
	"encoding/hex"
	"fmt"
	"strings"
	"testing"
	"time"

	"gno.land/p/g1j7l6ekxy82r9tav7d8jv3gp0h3xaunw2m2k3lx/puzzlerounds"
)

// Test identities (well-known test addresses from the Gno examples).
const (
	ownerAddr address = "g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5"
	aliceAddr address = "g1skl80cuz8zq3lul9pgz5pc35l2pfzgxgfpsqkx"
	bobAddr   address = "g1xrcglralkd8zaww0dn3q6qerh2xzq68h86z5r4"
)

// resetState re-initialises all realm state. `gno test` runs the package
// init once and shares state across tests, and init() leaves the owner
// empty in tests (no deployer), so each test resets explicitly.
func resetState() {
	owner = ownerAddr
	roundCount = 0
	totalSolves = 0
	rounds = make(map[int]puzzlerounds.Round)
	solved = make(map[int]map[address]bool)
	solvesOf = make(map[address]int)
	streakOf = make(map[address]int)
	lastDayOf = make(map[address]int64)
	seen = make(map[address]bool)
	solvers = nil
}

// hashHex returns the 64-char hex commitment for an answer, the same value
// an owner passes to CreateRound.
func hashHex(answer int) string {
	h := puzzlerounds.HashAnswer(answer)
	return hex.EncodeToString(h[:])
}

// expectAbort asserts that fn aborts (panics across the realm boundary)
// with exactly the given message.
func expectAbort(t *testing.T, want string, fn func()) {
	t.Helper()
	r := revive(fn)
	if r == nil {
		t.Fatalf("expected abort with %q, got none", want)
	}
	if got := fmt.Sprintf("%v", r); got != want {
		t.Fatalf("abort message = %q, want %q", got, want)
	}
}

// createRoundAsOwner creates an open round (window around the test VM's
// fixed time) and returns its ID. Caller must be the owner.
func createOpenRound(cur realm, t *testing.T, answer int) int {
	t.Helper()
	// NB: SetRealm only affects the frame it is called from, so it must
	// stay here in the same function that makes the cross call below.
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	now := time.Now().Unix()
	return CreateRound(cross(cur), "What is 6 x 7?", hashHex(answer), now, now+3600)
}

func TestCreateRound(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	now := time.Now().Unix()
	id := CreateRound(cross(cur), "What is 6 x 7?", hashHex(42), now, now+3600)
	if id != 1 {
		t.Fatalf("first round ID = %d, want 1", id)
	}
	if RoundCount() != 1 {
		t.Fatalf("RoundCount = %d, want 1", RoundCount())
	}
	round, ok := GetRound(1)
	if !ok {
		t.Fatalf("GetRound(1) not found")
	}
	if round.Question != "What is 6 x 7?" {
		t.Fatalf("question = %q", round.Question)
	}
	if round.Solves != 0 {
		t.Fatalf("new round solves = %d, want 0", round.Solves)
	}
	// Second round gets ID 2, using a 0x-prefixed hash (also accepted).
	id2 := CreateRound(cross(cur), "Second puzzle?", "0x"+hashHex(7), now, now+3600)
	if id2 != 2 {
		t.Fatalf("second round ID = %d, want 2", id2)
	}
}

func TestCreateRoundOnlyOwner(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	now := time.Now().Unix()
	expectAbort(t, "riddletavern: only owner can create rounds", func() {
		CreateRound(cross(cur), "Nope?", hashHex(1), now, now+3600)
	})
	if RoundCount() != 0 {
		t.Fatalf("RoundCount = %d after rejected create, want 0", RoundCount())
	}
}

func TestCreateRoundValidation(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	now := time.Now().Unix()
	// Zero hash.
	expectAbort(t, "riddletavern: answer hash must be 64 hex characters", func() {
		CreateRound(cross(cur), "Q?", "00", now-3600, now+3600)
	})
	// Bad hex.
	expectAbort(t, "riddletavern: answer hash must be 64 hex characters", func() {
		CreateRound(cross(cur), "Q?", "zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz", now-3600, now+3600)
	})
	// End before start.
	expectAbort(t, "riddletavern: end must be after start", func() {
		CreateRound(cross(cur), "Q?", hashHex(1), now+3600, now-3600)
	})
	// Start in the past (the test VM time is fixed at 1234567890).
	expectAbort(t, "riddletavern: start in the past", func() {
		CreateRound(cross(cur), "Q?", hashHex(1), now-7200, now-3600)
	})
	// Empty question.
	expectAbort(t, "riddletavern: empty question", func() {
		CreateRound(cross(cur), "", hashHex(1), now, now+3600)
	})
	if RoundCount() != 0 {
		t.Fatalf("RoundCount = %d after rejected creates, want 0", RoundCount())
	}
}

func TestSolveCorrect(cur realm, t *testing.T) {
	resetState()
	id := createOpenRound(cur, t, 42)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	Solve(cross(cur), id, 42)
	if SolvesOf(aliceAddr) != 1 {
		t.Fatalf("alice solves = %d, want 1", SolvesOf(aliceAddr))
	}
	if StreakOf(aliceAddr) != 1 {
		t.Fatalf("alice streak = %d, want 1", StreakOf(aliceAddr))
	}
	if TotalSolves() != 1 {
		t.Fatalf("TotalSolves = %d, want 1", TotalSolves())
	}
	if !SolvedBy(id, aliceAddr) {
		t.Fatalf("alice should be marked solved")
	}
	round, _ := GetRound(id)
	if round.Solves != 1 {
		t.Fatalf("round solves = %d, want 1", round.Solves)
	}
}

func TestSolveWrongAnswer(cur realm, t *testing.T) {
	resetState()
	id := createOpenRound(cur, t, 42)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, "riddletavern: wrong answer", func() {
		Solve(cross(cur), id, 43)
	})
	if SolvesOf(aliceAddr) != 0 {
		t.Fatalf("alice solves = %d after wrong answer, want 0", SolvesOf(aliceAddr))
	}
	if TotalSolves() != 0 {
		t.Fatalf("TotalSolves = %d after wrong answer, want 0", TotalSolves())
	}
}

func TestSolveDouble(cur realm, t *testing.T) {
	resetState()
	id := createOpenRound(cur, t, 42)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	Solve(cross(cur), id, 42)
	expectAbort(t, "riddletavern: already solved", func() {
		Solve(cross(cur), id, 42)
	})
	if SolvesOf(aliceAddr) != 1 {
		t.Fatalf("alice solves = %d after double solve, want 1", SolvesOf(aliceAddr))
	}
}

func TestSolveInvalidRound(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, "riddletavern: invalid round", func() {
		Solve(cross(cur), 99, 42)
	})
	expectAbort(t, "riddletavern: invalid round", func() {
		Solve(cross(cur), 0, 42)
	})
}

func TestSolveOutsideWindow(cur realm, t *testing.T) {
	resetState()
	now := time.Now().Unix()
	// Round that has not opened yet.
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	future := CreateRound(cross(cur), "Future?", hashHex(42), now+3600, now+7200)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, "riddletavern: round not open", func() {
		Solve(cross(cur), future, 42)
	})
	// Round that already sealed: created open, then... the test VM time is
	// fixed, so a sealed round cannot be created via CreateRound (start in
	// the past is rejected). Instead, verify the window check rejects a
	// round whose end is before the fixed test time by creating it with a
	// start in the past is impossible — so check the not-open case above
	// plus a zero-length window rejection at creation. The sealed case is
	// covered by the same IsOpen check in the package tests.
	if SolvesOf(aliceAddr) != 0 {
		t.Fatalf("alice solves = %d, want 0", SolvesOf(aliceAddr))
	}
}

func TestLeaderboard(cur realm, t *testing.T) {
	resetState()
	id := createOpenRound(cur, t, 42)
	id2 := 0
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	now := time.Now().Unix()
	id2 = CreateRound(cross(cur), "Second?", hashHex(7), now, now+3600)

	// Alice solves both rounds; Bob solves one.
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	Solve(cross(cur), id, 42)
	Solve(cross(cur), id2, 7)
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	Solve(cross(cur), id, 42)

	leaders := Leaderboard()
	if len(leaders) != 2 {
		t.Fatalf("leaderboard size = %d, want 2", len(leaders))
	}
	if leaders[0].Solver != aliceAddr || leaders[0].Solves != 2 {
		t.Fatalf("leader[0] = %v (%d solves), want alice (2)", leaders[0].Solver, leaders[0].Solves)
	}
	if leaders[1].Solver != bobAddr || leaders[1].Solves != 1 {
		t.Fatalf("leader[1] = %v (%d solves), want bob (1)", leaders[1].Solver, leaders[1].Solves)
	}
	// Same-day second solve does not change the streak.
	if StreakOf(aliceAddr) != 1 {
		t.Fatalf("alice streak = %d, want 1 (same-day solves)", StreakOf(aliceAddr))
	}
}

func TestTransferOwnership(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, "riddletavern: only owner can transfer ownership", func() {
		TransferOwnership(cross(cur), aliceAddr)
	})
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	TransferOwnership(cross(cur), aliceAddr)
	if Owner() != aliceAddr {
		t.Fatalf("owner = %v, want alice", Owner())
	}
	// Old owner can no longer create rounds.
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	now := time.Now().Unix()
	expectAbort(t, "riddletavern: only owner can create rounds", func() {
		CreateRound(cross(cur), "Q?", hashHex(1), now, now+3600)
	})
}

func TestRender(cur realm, t *testing.T) {
	resetState()
	// Empty state renders without rounds.
	out := Render("")
	if !strings.Contains(out, "Riddle Tavern") {
		t.Fatalf("render missing title: %q", out)
	}
	if !strings.Contains(out, "No rounds yet") {
		t.Fatalf("render should say no rounds yet: %q", out)
	}
	id := createOpenRound(cur, t, 42)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	Solve(cross(cur), id, 42)
	out = Render("")
	if !strings.Contains(out, "Round 1") {
		t.Fatalf("render missing round: %q", out)
	}
	if !strings.Contains(out, "What is 6 x 7?") {
		t.Fatalf("render missing puzzle: %q", out)
	}
	if !strings.Contains(out, "g1skl80cuz8zq3lul9pgz5pc35l2pfzgxgfpsqkx") {
		t.Fatalf("render missing solver on leaderboard: %q", out)
	}
	// Specific round path.
	out = Render("/1")
	if !strings.Contains(out, "Round 1") {
		t.Fatalf("render /1 missing round: %q", out)
	}
}

// Package mequest is MeQuest: quests that verify themselves.
//
// Projects lock GNOT rewards in this realm when they create a quest.
// Coins can only leave through a verified claim, a split settle, or a
// refund of the unclaimed remainder to the funder after expiry.
// Winners get a soulbound rarity card (Common/Rare/Epic/Legendary).
package mqdev2

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

// ---------- rules ----------

const (
	Common    = 1
	Rare      = 2
	Epic      = 3
	Legendary = 4

	KindManual = "manual" // project reviews a proof
	KindPush   = "push"   // partner realm calls Complete
	KindHold   = "hold"   // wallet holds at least Arg ugnot

	PayFixed = "fixed" // style A: Reward per winner, paid on claim
	PaySplit = "split" // style B: pool split equally after expiry

	DailyCap = 10
	Season   = "S1"
	daySecs  = 86400
)

var (
	admin     address = "g1hwcp3aah5ehwq7zvz74c4x5nzewtgz2qmwjj0l"
	supplyCap         = map[int]int{Common: 0, Rare: 500, Epic: 100, Legendary: 10} // 0 = unlimited
	cardPts           = map[int]int64{Common: 10, Rare: 50, Epic: 200, Legendary: 1000}
	rarityName        = map[int]string{Common: "Common", Rare: "Rare", Epic: "Epic", Legendary: "Legendary"}
	rankName          = map[int]string{0: "Newcomer", Common: "Rookie", Rare: "Explorer", Epic: "Pathfinder", Legendary: "Legend"}
)

// ---------- state ----------

type Card struct {
	QuestID int
	Title   string
	Rarity  int
	Serial  int
	Season  string
	At      int64
}

type Quest struct {
	ID      int
	Title   string
	Desc    string
	Funder  address
	Rarity  int
	Kind    string
	Arg     string // hold: min ugnot; push: partner pkg path
	Pay     string
	Reward  int64 // fixed: ugnot per winner
	Pool    int64 // ugnot still locked for this quest
	Funded  int64
	Max     int
	Expires int64
	Settled bool
	Winners []address
	won     map[address]bool
	pending map[address]string
}

var (
	quests   []*Quest
	cards    = map[address][]Card{}
	points   = map[address]int64{}
	daily    = map[string]int{}
	projects = map[address]bool{}
	players  []address
	log      []string
)

// ---------- projects ----------

// CreateQuest locks the sent ugnot as the quest pool. Send coins with the tx.
func CreateQuest(cur realm, title, desc string, rarity int, kind, arg, pay string, max int, days int) int {
	requireWallet(cur)
	funder := cur.Previous().Address()
	if rarity < Common || rarity > Legendary {
		panic("bad rarity")
	}
	if rarity >= Epic && !projects[funder] && funder != admin {
		panic("only approved projects can create Epic or Legendary quests")
	}
	if kind != KindManual && kind != KindPush && kind != KindHold {
		panic("bad kind")
	}
	if kind == KindHold {
		if _, err := strconv.ParseInt(arg, 10, 64); err != nil {
			panic("hold quests need a ugnot amount as arg")
		}
	}
	if pay != PayFixed && pay != PaySplit {
		panic("bad pay style")
	}
	if pay == PaySplit && rarity < Epic && kind != KindPush {
		panic("split pay is for Epic/Legendary or partner quests")
	}
	if max < 1 || (supplyCap[rarity] > 0 && max > supplyCap[rarity]) {
		panic("max winners out of range for this rarity")
	}
	if days < 1 || days > 90 {
		panic("days must be 1-90")
	}
	if strings.TrimSpace(title) == "" {
		panic("title required")
	}
	sent := unsafe.OriginSend().AmountOf("ugnot")
	if sent <= 0 {
		panic("send ugnot to fund the pool")
	}
	q := &Quest{
		ID: len(quests) + 1, Title: title, Desc: desc, Funder: funder,
		Rarity: rarity, Kind: kind, Arg: arg, Pay: pay,
		Pool: sent, Funded: sent, Max: max,
		Expires: time.Now().Unix() + int64(days)*daySecs,
		won: map[address]bool{}, pending: map[address]string{},
	}
	if pay == PayFixed {
		if sent%int64(max) != 0 {
			panic("pool must divide evenly by max winners")
		}
		q.Reward = sent / int64(max)
	}
	quests = append(quests, q)
	note("quest #" + itoa(q.ID) + " created, pool " + gnot(sent))
	return q.ID
}

// Review approves or rejects a manual proof. Funder or admin only.
func Review(cur realm, id int, wallet address, ok bool) {
	q := mustQuest(id)
	caller := cur.Previous().Address()
	if caller != q.Funder && caller != admin {
		panic("only the quest funder can review")
	}
	if _, has := q.pending[wallet]; !has {
		panic("no pending proof")
	}
	delete(q.pending, wallet)
	if ok {
		award(cur, q, wallet)
	} else {
		note("quest #" + itoa(id) + " proof rejected for " + short(wallet))
	}
}

// Refund returns the unclaimed pool of an expired fixed quest to its funder.
func Refund(cur realm, id int) {
	q := mustQuest(id)
	if q.Pay != PayFixed {
		panic("split quests use Settle")
	}
	if time.Now().Unix() < q.Expires {
		panic("quest still running: pool is locked")
	}
	if q.Pool == 0 {
		panic("nothing to refund")
	}
	amt := q.Pool
	q.Pool = 0
	send(cur, q.Funder, amt)
	note("quest #" + itoa(id) + " refunded " + gnot(amt) + " to funder")
}

// Settle pays a split quest after expiry. Anyone can call it.
func Settle(cur realm, id int) {
	q := mustQuest(id)
	if q.Pay != PaySplit || q.Settled {
		panic("not a split quest or already settled")
	}
	if time.Now().Unix() < q.Expires {
		panic("quest still running")
	}
	q.Settled = true
	n := int64(len(q.Winners))
	if n > 0 {
		share := q.Pool / n
		for _, w := range q.Winners {
			send(cur, w, share)
			q.Pool -= share
		}
		note("quest #" + itoa(id) + " split " + gnot(share) + " x " + itoa(int(n)))
	}
	if q.Pool > 0 {
		left := q.Pool
		q.Pool = 0
		send(cur, q.Funder, left)
	}
}

// ---------- questers ----------

// Claim runs the quest's own check on the caller and pays if it passes.
func Claim(cur realm, id int) {
	requireWallet(cur)
	q := mustQuest(id)
	user := cur.Previous().Address()
	switch q.Kind {
	case KindHold:
		min, _ := strconv.ParseInt(q.Arg, 10, 64)
		bal := banker.NewReadonlyBanker().GetCoin(user, "ugnot")
		if bal < min {
			panic("check failed: hold at least " + gnot(min))
		}
	case KindManual:
		panic("this quest needs a proof: use Submit")
	case KindPush:
		panic("finish this quest on the partner app: " + q.Arg)
	}
	award(cur, q, user)
}

// Submit sends a proof (link or text) for a manual quest.
func Submit(cur realm, id int, proof string) {
	requireWallet(cur)
	q := mustQuest(id)
	user := cur.Previous().Address()
	if q.Kind != KindManual {
		panic("not a manual quest")
	}
	open(q, user)
	if len(proof) == 0 || len(proof) > 280 {
		panic("proof must be 1-280 chars")
	}
	q.pending[user] = proof
	note("quest #" + itoa(id) + " proof submitted by " + short(user))
}

// Complete is called by the partner realm named in a push quest.
func Complete(cur realm, id int, wallet address) {
	q := mustQuest(id)
	if q.Kind != KindPush {
		panic("not a push quest")
	}
	if cur.Previous().PkgPath() != q.Arg {
		panic("only " + q.Arg + " can complete this quest")
	}
	award(cur, q, wallet)
}

// ---------- admin ----------

func ApproveProject(cur realm, p address, on bool) {
	onlyAdmin(cur)
	projects[p] = on
}

// Revoke removes a card from a cheater wallet.
func Revoke(cur realm, wallet address, id int) {
	onlyAdmin(cur)
	list := cards[wallet]
	for i, c := range list {
		if c.QuestID == id {
			cards[wallet] = append(list[:i], list[i+1:]...)
			points[wallet] -= cardPts[c.Rarity]
			note("card from quest #" + itoa(id) + " revoked from " + short(wallet))
			return
		}
	}
	panic("wallet has no card from that quest")
}

// ---------- read-only checks (other realms can call these) ----------

func HasCard(wallet address, id int) bool {
	for _, c := range cards[wallet] {
		if c.QuestID == id {
			return true
		}
	}
	return false
}

func BestRarity(wallet address) int {
	best := 0
	for _, c := range cards[wallet] {
		if c.Rarity > best {
			best = c.Rarity
		}
	}
	return best
}

func HasRarity(wallet address, min int) bool { return BestRarity(wallet) >= min }
func PointsOf(wallet address) int64          { return points[wallet] }
func CardCount(wallet address) int           { return len(cards[wallet]) }

// ---------- internals ----------

func award(cur realm, q *Quest, user address) {
	open(q, user)
	if q.Rarity == Legendary && BestRarity(user) < Epic {
		panic("Legendary needs an Epic card first")
	}
	if len(q.Winners) >= q.Max {
		panic("all winner slots are taken")
	}
	day := strconv.FormatInt(time.Now().Unix()/daySecs, 10)
	key := string(user) + ":" + day
	if daily[key] >= DailyCap {
		panic("daily cap reached: 10 claims per day")
	}
	daily[key]++

	q.won[user] = true
	q.Winners = append(q.Winners, user)
	if _, seen := points[user]; !seen {
		players = append(players, user)
	}
	cards[user] = append(cards[user], Card{
		QuestID: q.ID, Title: q.Title, Rarity: q.Rarity,
		Serial: len(q.Winners), Season: Season, At: time.Now().Unix(),
	})
	points[user] += cardPts[q.Rarity]

	msg := short(user) + " won " + rarityName[q.Rarity] + " #" + itoa(len(q.Winners)) + " on quest #" + itoa(q.ID)
	if q.Pay == PayFixed {
		q.Pool -= q.Reward
		send(cur, user, q.Reward)
		msg += ", paid " + gnot(q.Reward)
	}
	note(msg)
}

func open(q *Quest, user address) {
	if time.Now().Unix() >= q.Expires {
		panic("quest expired")
	}
	if q.won[user] {
		panic("already claimed: one win per wallet")
	}
}

func send(cur realm, to address, amt int64) {
	if amt <= 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{"ugnot", amt}})
}

// requireWallet blocks calls routed through other realms (anti-farming bots,
// and makes sure sent coins really came from the caller).
func requireWallet(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("call this directly from your wallet")
	}
}

func onlyAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
}

func mustQuest(id int) *Quest {
	if id < 1 || id > len(quests) {
		panic("quest not found")
	}
	return quests[id-1]
}

func note(s string) {
	log = append(log, s)
	if len(log) > 50 {
		log = log[len(log)-50:]
	}
}

func itoa(n int) string { return strconv.Itoa(n) }

func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	f := strings.TrimRight(strconv.FormatInt(frac+1000000, 10)[1:], "0")
	return strconv.FormatInt(whole, 10) + "." + f + " GNOT"
}

func short(a address) string {
	s := string(a)
	if len(s) < 12 {
		return s
	}
	return s[:7] + "…" + s[len(s)-4:]
}

// ---------- pages ----------

func Render(path string) string {
	switch {
	case path == "":
		return renderBoard()
	case strings.HasPrefix(path, "q/"):
		id, err := strconv.Atoi(path[2:])
		if err != nil || id < 1 || id > len(quests) {
			return "quest not found"
		}
		return renderQuest(quests[id-1])
	case strings.HasPrefix(path, "p/"):
		return renderPassport(address(path[2:]))
	case path == "top":
		return renderTop()
	}
	return "404"
}

func renderBoard() string {
	s := "# MeQuest\n_Quests that verify themselves._ Season " + Season + "\n\n"
	s += "[Leaderboard](:top)\n\n## Quests\n\n"
	if len(quests) == 0 {
		s += "No quests yet.\n"
	}
	for i := len(quests) - 1; i >= 0; i-- {
		q := quests[i]
		s += "- [#" + itoa(q.ID) + " " + q.Title + "](:q/" + itoa(q.ID) + ") · " + rarityName[q.Rarity] +
			" · " + itoa(len(q.Winners)) + "/" + itoa(q.Max) + " claimed · pool " + gnot(q.Pool) + " left\n"
	}
	s += "\n## Live feed\n\n"
	for i := len(log) - 1; i >= 0 && i >= len(log)-10; i-- {
		s += "- " + log[i] + "\n"
	}
	return s
}

func renderQuest(q *Quest) string {
	s := "# #" + itoa(q.ID) + " " + q.Title + "\n\n" + q.Desc + "\n\n"
	s += "- Card: **" + rarityName[q.Rarity] + "** (" + Season + ")\n"
	s += "- Check: " + q.Kind
	if q.Arg != "" {
		s += " `" + q.Arg + "`"
	}
	s += "\n- Pay: " + q.Pay
	if q.Pay == PayFixed {
		s += ", " + gnot(q.Reward) + " per winner"
	}
	s += "\n- Pool: " + gnot(q.Pool) + " locked of " + gnot(q.Funded) + " funded\n"
	s += "- Winners: " + itoa(len(q.Winners)) + "/" + itoa(q.Max) + "\n"
	s += "- Funder: " + short(q.Funder) + "\n- Ends: " + time.Unix(q.Expires, 0).UTC().Format("2006-01-02 15:04 UTC") + "\n"
	return s
}

func renderPassport(w address) string {
	best := BestRarity(w)
	s := "# Passport: " + short(w) + "\n\n**" + rankName[best] + "** · " +
		strconv.FormatInt(points[w], 10) + " pts · " + itoa(len(cards[w])) + " cards\n\n"
	for _, c := range cards[w] {
		s += "- " + rarityName[c.Rarity] + " · " + c.Title + " · #" + itoa(c.Serial) + " · " + c.Season + "\n"
	}
	return s
}

func renderTop() string {
	list := make([]address, len(players))
	copy(list, players)
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && points[list[j]] > points[list[j-1]]; j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
	s := "# Season " + Season + " leaderboard\n\n"
	for i, w := range list {
		if i == 10 {
			break
		}
		s += itoa(i+1) + ". [" + short(w) + "](:p/" + string(w) + ") · " + strconv.FormatInt(points[w], 10) + " pts\n"
	}
	return s
}

package mequest

// JSON views for the website, served through Render("api/...").
// Read them with the RPC query vm/qrender, e.g. "<pkgpath>:api/quests".

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/sys/users"
)

func renderAPI(path string) string {
	switch {
	case path == "stats":
		return apiStats()
	case path == "quests":
		out := make([]string, 0, len(quests))
		for _, q := range quests {
			out = append(out, questJSON(q, false))
		}
		return "[" + strings.Join(out, ",") + "]"
	case strings.HasPrefix(path, "q/"):
		id, err := strconv.Atoi(path[2:])
		if err != nil || id < 1 || id > len(quests) {
			return "null"
		}
		return questJSON(quests[id-1], true)
	case strings.HasPrefix(path, "p/"):
		return passportJSON(address(path[2:]))
	case path == "top":
		return topJSON()
	case path == "feed":
		out := []string{}
		for i := len(log) - 1; i >= 0; i-- {
			out = append(out, "{\"at\":"+i64(log[i].At)+",\"msg\":"+js(log[i].Msg)+"}")
		}
		return "[" + strings.Join(out, ",") + "]"
	case path == "receipts":
		out := []string{}
		for i := len(receipts) - 1; i >= 0; i-- {
			r := receipts[i]
			out = append(out, "{\"n\":"+strconv.Itoa(r.N)+",\"quest\":"+strconv.Itoa(r.Quest)+
				",\"title\":"+js(quests[r.Quest-1].Title)+",\"who\":"+who(r.Who)+",\"ok\":"+strconv.FormatBool(r.Ok)+
				",\"check\":"+js(r.Check)+",\"paid\":"+i64(r.Paid)+",\"rarity\":"+strconv.Itoa(quests[r.Quest-1].Rarity)+
				",\"art\":"+js(quests[r.Quest-1].Art)+",\"height\":"+i64(r.Height)+",\"at\":"+i64(r.At)+"}")
		}
		return "[" + strings.Join(out, ",") + "]"
	case path == "projects":
		out := []string{}
		for a, on := range projects {
			if on {
				out = append(out, who(a))
			}
		}
		return "{\"admin\":" + js(string(admin)) + ",\"approved\":[" + strings.Join(out, ",") + "]}"
	}
	return "null"
}

func apiStats() string {
	locked := int64(0)
	open := 0
	now := time.Now().Unix()
	for _, q := range quests {
		locked += q.Pool
		if now < q.Expires && len(q.Winners) < q.Max {
			open++
		}
	}
	return "{\"quests\":" + strconv.Itoa(len(quests)) + ",\"open\":" + strconv.Itoa(open) +
		",\"locked\":" + i64(locked) + ",\"paid\":" + i64(paidOut) +
		",\"cards\":" + strconv.Itoa(minted) + ",\"players\":" + strconv.Itoa(len(players)) + ",\"joined\":" + strconv.Itoa(joined) +
		",\"season\":" + js(Season) + ",\"now\":" + i64(now) + "}"
}

func questJSON(q *Quest, full bool) string {
	s := "{\"id\":" + strconv.Itoa(q.ID) + ",\"title\":" + js(q.Title) + ",\"desc\":" + js(q.Desc) +
		",\"art\":" + js(q.Art) + ",\"funder\":" + who(q.Funder) + ",\"rarity\":" + strconv.Itoa(q.Rarity) +
		",\"kind\":" + js(q.Kind) + ",\"arg\":" + js(q.Arg) + ",\"pay\":" + js(q.Pay) +
		",\"reward\":" + i64(q.Reward) + ",\"pool\":" + i64(q.Pool) + ",\"funded\":" + i64(q.Funded) +
		",\"max\":" + strconv.Itoa(q.Max) + ",\"claimed\":" + strconv.Itoa(len(q.Winners)) +
		",\"pending\":" + strconv.Itoa(len(q.pending)) + ",\"expires\":" + i64(q.Expires) +
		",\"settled\":" + strconv.FormatBool(q.Settled)
	if full {
		w := []string{}
		for i, a := range q.Winners {
			w = append(w, "{\"serial\":"+strconv.Itoa(i+1)+",\"who\":"+who(a)+"}")
		}
		p := []string{}
		for a, proof := range q.pending {
			p = append(p, "{\"who\":"+who(a)+",\"proof\":"+js(proof)+"}")
		}
		s += ",\"winners\":[" + strings.Join(w, ",") + "],\"queue\":[" + strings.Join(p, ",") + "]"
	}
	return s + "}"
}

func passportJSON(a address) string {
	cs := []string{}
	for _, c := range cards[a] {
		cs = append(cs, "{\"quest\":"+strconv.Itoa(c.QuestID)+",\"title\":"+js(c.Title)+",\"art\":"+js(c.Art)+
			",\"rarity\":"+strconv.Itoa(c.Rarity)+",\"serial\":"+strconv.Itoa(c.Serial)+
			",\"season\":"+js(c.Season)+",\"at\":"+i64(c.At)+"}")
	}
	pend := []string{}
	for _, q := range quests {
		if _, ok := q.pending[a]; ok {
			pend = append(pend, strconv.Itoa(q.ID))
		}
	}
	best := BestRarity(a)
	day := strconv.FormatInt(time.Now().Unix()/daySecs, 10)
	return "{\"who\":" + who(a) + ",\"rank\":" + js(rankName[best]) + ",\"best\":" + strconv.Itoa(best) +
		",\"points\":" + i64(points[a]) + ",\"today\":" + strconv.Itoa(daily[string(a)+":"+day]) +
		",\"dailyCap\":" + strconv.Itoa(DailyCap) + ",\"streak\":" + strconv.Itoa(StreakOf(a)) +
		",\"checkedToday\":" + strconv.FormatBool(lastDay[a] == time.Now().Unix()/daySecs && streak[a] > 0) +
		",\"joinRank\":" + strconv.Itoa(joinRank[a]) + ",\"invites\":" + strconv.Itoa(invitesDone[a]) +
		",\"hasInviter\":" + strconv.FormatBool(inviter[a] != "") + ",\"projects\":" + strconv.Itoa(ProjectsDone(a)) +
		",\"posted\":" + strconv.Itoa(posted[a]) + ",\"approved\":" + strconv.FormatBool(projects[a] || a == admin) +
		",\"cards\":[" + strings.Join(cs, ",") + "],\"pending\":[" + strings.Join(pend, ",") + "]}"
}

func topJSON() string {
	list := ranked()
	out := []string{}
	for i, a := range list {
		if i == 50 {
			break
		}
		art := ""
		best := 0
		for _, c := range cards[a] {
			if c.Rarity > best {
				best, art = c.Rarity, c.Art
			}
		}
		out = append(out, "{\"who\":"+who(a)+",\"points\":"+i64(points[a])+",\"best\":"+strconv.Itoa(best)+",\"bestArt\":"+js(art)+
			",\"cards\":"+strconv.Itoa(len(cards[a]))+"}")
	}
	return "[" + strings.Join(out, ",") + "]"
}

func ranked() []address {
	list := make([]address, len(players))
	copy(list, players)
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && points[list[j]] > points[list[j-1]]; j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
	return list
}

// who returns {"addr":..., "name":...}; name is the wallet's unique
// gno.land username from r/sys/users, or "" if it has none.
func who(a address) string {
	name := ""
	if u := users.ResolveAddress(a); u != nil {
		name = u.Name()
	}
	return "{\"addr\":" + js(string(a)) + ",\"name\":" + js(name) + "}"
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

// js quotes a string as a JSON string.
func js(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString("\\\"")
		case r == '\\':
			b.WriteString("\\\\")
		case r == '\n':
			b.WriteString("\\n")
		case r < 0x20:
			h := strconv.FormatInt(int64(r), 16)
			b.WriteString("\\u" + strings.Repeat("0", 4-len(h)) + h)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package mequest

// Self-verifying checks. Every rule here is public code: the board runs it
// on the caller's wallet and only pays when it returns no reason.

import (
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/r/sys/users"
)

const (
	KindCheckin  = "checkin"  // check-in streak of at least Arg days (1 = first check-in)
	KindEarly    = "early"    // among the first Arg wallets to join MeQuest
	KindInvites  = "invites"  // at least Arg invited friends earned a card
	KindProjects = "projects" // cards from at least Arg different projects
	KindCards    = "cards"    // own at least Arg cards
	KindPosted   = "posted"   // funded at least Arg quests as a project
	KindMyRealm  = "myrealm"  // your own realm (gno.land/r/<your addr>/...) calls ProveRealm
	KindGrant    = "grant"    // given by the quest funder (e.g. season top 3)
)

var (
	joinRank    = map[address]int{}
	joined      int
	streak      = map[address]int{}
	lastDay     = map[address]int64{}
	inviter     = map[address]address{}
	invitesDone = map[address]int{}
	posted      = map[address]int{}
)

func validKind(kind, arg string) string {
	switch kind {
	case KindManual, KindPush, KindMyRealm, KindGrant, KindName:
		return ""
	case KindHold:
		if n, err := strconv.ParseInt(arg, 10, 64); err != nil || n < 1 {
			return "hold quests need a ugnot amount as arg"
		}
		return ""
	case KindCard:
		for _, part := range strings.Split(arg, ",") {
			if n, err := strconv.Atoi(strings.TrimSpace(part)); err != nil || n < 1 || n > len(quests) {
				return "card quests need existing quest ids as arg, like 1,2,3"
			}
		}
		return ""
	case KindCheckin, KindEarly, KindInvites, KindProjects, KindCards, KindPosted:
		if n, err := strconv.Atoi(arg); err != nil || n < 1 {
			return "this kind needs a number as arg"
		}
		return ""
	}
	return "bad kind"
}

// verifyReason runs the quest's own check. "" means the wallet passes.
func verifyReason(q *Quest, user address) string {
	n, _ := strconv.Atoi(q.Arg)
	switch q.Kind {
	case KindHold:
		min, _ := strconv.ParseInt(q.Arg, 10, 64)
		if banker.NewReadonlyBanker().GetCoin(user, "ugnot") < min {
			return "check failed: hold at least " + gnot(min)
		}
	case KindName:
		if users.ResolveAddress(user) == nil {
			return "check failed: register a gno.land username first"
		}
	case KindCard:
		for _, part := range strings.Split(q.Arg, ",") {
			id, _ := strconv.Atoi(strings.TrimSpace(part))
			if !HasCard(user, id) {
				return "check failed: you need the card from quest #" + strconv.Itoa(id) + " first"
			}
		}
	case KindCheckin:
		if s := StreakOf(user); s < n {
			return "check failed: check-in streak is " + strconv.Itoa(s) + ", needs " + q.Arg
		}
	case KindEarly:
		r := joinRank[user]
		if r == 0 {
			return "check failed: you haven't joined yet, check in first"
		}
		if r > n {
			return "check failed: you joined as wallet #" + strconv.Itoa(r) + ", only the first " + q.Arg + " get this"
		}
	case KindInvites:
		if invitesDone[user] < n {
			return "check failed: " + strconv.Itoa(invitesDone[user]) + " invited friends earned a card, needs " + q.Arg
		}
	case KindProjects:
		if p := ProjectsDone(user); p < n {
			return "check failed: cards from " + strconv.Itoa(p) + " projects, needs " + q.Arg
		}
	case KindCards:
		if len(cards[user]) < n {
			return "check failed: you own " + strconv.Itoa(len(cards[user])) + " cards, needs " + q.Arg
		}
	case KindPosted:
		if posted[user] < n {
			return "check failed: post a funded quest first"
		}
	case KindManual:
		return "this quest needs a proof: use Submit"
	case KindPush:
		return "finish this quest on the partner app: " + q.Arg
	case KindMyRealm:
		return "deploy your own realm and have it call ProveRealm"
	case KindGrant:
		return "this card is given by the project"
	}
	return ""
}

// gateReason checks board rules shared by every payout.
func gateReason(q *Quest, user address) string {
	if time.Now().Unix() >= q.Expires {
		return "quest expired"
	}
	if q.won[user] {
		return "already claimed: one win per wallet"
	}
	if q.Rarity == Legendary && BestRarity(user) < Epic {
		return "Legendary needs an Epic card first"
	}
	if len(q.Winners) >= q.Max {
		return "all winner slots are taken"
	}
	day := strconv.FormatInt(time.Now().Unix()/daySecs, 10)
	if daily[string(user)+":"+day] >= DailyCap {
		return "daily cap reached: 10 claims per day"
	}
	return ""
}

// CanClaim is a free read-only dry run of Claim: "ok" or the reason it would fail.
func CanClaim(wallet address, id int) string {
	if id < 1 || id > len(quests) {
		return "quest not found"
	}
	q := quests[id-1]
	if r := gateReason(q, wallet); r != "" {
		return r
	}
	if r := verifyReason(q, wallet); r != "" {
		return r
	}
	return "ok"
}

// CheckIn records today's check-in and grows your streak.
func CheckIn(cur realm) int {
	requireWallet(cur)
	user := cur.Previous().Address()
	today := time.Now().Unix() / daySecs
	last, seen := lastDay[user]
	if seen && last == today {
		panic("already checked in today")
	}
	if seen && last == today-1 {
		streak[user]++
	} else {
		streak[user] = 1
	}
	lastDay[user] = today
	touch(user)
	return streak[user]
}

// StreakOf returns the live streak (0 if a day was missed).
func StreakOf(wallet address) int {
	last, seen := lastDay[wallet]
	if !seen || time.Now().Unix()/daySecs-last > 1 {
		return 0
	}
	return streak[wallet]
}

// SetInviter links you to the friend who invited you. Once, before your first card.
func SetInviter(cur realm, friend address) {
	requireWallet(cur)
	user := cur.Previous().Address()
	if friend == user || !friend.IsValid() {
		panic("invalid inviter")
	}
	if _, ok := inviter[user]; ok {
		panic("inviter already set")
	}
	if len(cards[user]) > 0 {
		panic("set your inviter before your first card")
	}
	inviter[user] = friend
	touch(user)
}

// ProveRealm must be called by a realm deployed under the caller's own
// address: gno.land/r/<your g1 address>/anything. That path proves you built it.
func ProveRealm(cur realm, id int) {
	q := mustQuest(id)
	if q.Kind != KindMyRealm {
		panic("not a first-realm quest")
	}
	user := unsafe.OriginCaller()
	prev := cur.Previous()
	if !prev.IsCode() || !strings.HasPrefix(prev.PkgPath(), "gno.land/r/"+string(user)+"/") {
		panic("call this from a realm under gno.land/r/" + string(user) + "/")
	}
	award(cur, q, user)
}

// Grant gives a grant-kind card. Quest funder only (e.g. Season Champion).
func Grant(cur realm, id int, wallet address) {
	q := mustQuest(id)
	if q.Kind != KindGrant {
		panic("not a grant quest")
	}
	if c := cur.Previous().Address(); c != q.Funder && c != admin {
		panic("only the quest funder can grant")
	}
	award(cur, q, wallet)
}

func ProjectsDone(wallet address) int {
	seen := map[address]bool{}
	for _, c := range cards[wallet] {
		seen[quests[c.QuestID-1].Funder] = true
	}
	return len(seen)
}

func JoinRank(wallet address) int  { return joinRank[wallet] }
func InvitesDone(wallet address) int { return invitesDone[wallet] }
func InviterOf(wallet address) address { return inviter[wallet] }

func touch(a address) {
	if joinRank[a] == 0 {
		joined++
		joinRank[a] = joined
	}
}

// checkLabel is the short proof line shown on a receipt.
func checkLabel(q *Quest) string {
	switch q.Kind {
	case KindHold:
		if mustInt64(q.Arg) < 1000 {
			return "holds GNOT → true"
		}
		return "balance >= " + gnot(mustInt64(q.Arg)) + " → true"
	case KindName:
		return "users.ResolveAddress → found"
	case KindCard:
		return "owns cards " + q.Arg + " → true"
	case KindCheckin:
		return "streak >= " + q.Arg + " → true"
	case KindEarly:
		return "join rank <= " + q.Arg + " → true"
	case KindInvites:
		return "invited friends >= " + q.Arg + " → true"
	case KindProjects:
		return "projects done >= " + q.Arg + " → true"
	case KindCards:
		return "cards owned >= " + q.Arg + " → true"
	case KindPosted:
		return "quests posted >= " + q.Arg + " → true"
	case KindManual:
		return "project review → approved"
	case KindPush:
		parts := strings.Split(q.Arg, "/")
		return "reported by the " + parts[len(parts)-1] + " realm"
	case KindMyRealm:
		return "caller realm path → yours"
	case KindGrant:
		return "granted by project"
	}
	return "verified"
}

func mustInt64(s string) int64 {
	n, _ := strconv.ParseInt(s, 10, 64)
	return n
}

// Package mequest is MeQuest: quests that verify themselves.
//
// Projects lock GNOT rewards in this realm when they create a quest.
// Coins can only leave through a verified claim, a split settle, or a
// refund of the unclaimed remainder to the funder after expiry.
// Winners get a soulbound rarity card (Common/Rare/Epic/Legendary).
package mequest

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

// ---------- rules ----------

const (
	Common    = 1
	Rare      = 2
	Epic      = 3
	Legendary = 4

	KindManual = "manual" // project reviews a proof
	KindPush   = "push"   // partner realm calls Complete
	KindHold   = "hold"   // wallet holds at least Arg ugnot
	KindName   = "name"   // wallet has a registered gno.land username
	KindCard   = "card"   // wallet owns the card from quest Arg (quest chain)

	PayFixed = "fixed" // style A: Reward per winner, paid on claim
	PaySplit = "split" // style B: pool split equally after expiry

	DailyCap = 10
	Season   = "S1"
	daySecs  = 86400
)

var (
	admin     address = "g1pkghjdzs4xe9j9fhp4va6glkqpc2cuwzslfcjh"
	supplyCap         = map[int]int{Common: 0, Rare: 500, Epic: 100, Legendary: 10} // 0 = unlimited
	cardPts           = map[int]int64{Common: 10, Rare: 50, Epic: 200, Legendary: 1000}
	rarityName        = map[int]string{Common: "Common", Rare: "Rare", Epic: "Epic", Legendary: "Legendary"}
	rankName          = map[int]string{0: "Newcomer", Common: "Rookie", Rare: "Explorer", Epic: "Pathfinder", Legendary: "Legend"}
)

// ---------- state ----------

type Card struct {
	QuestID int
	Title   string
	Art     string
	Rarity  int
	Serial  int
	Season  string
	At      int64
}

type Quest struct {
	ID      int
	Title   string
	Desc    string
	Art     string // card art key used by the website
	Funder  address
	Rarity  int
	Kind    string
	Arg     string // hold: min ugnot; push: partner pkg path
	Pay     string
	Reward  int64 // fixed: ugnot per winner
	Pool    int64 // ugnot still locked for this quest
	Funded  int64
	Max     int
	Expires int64
	Settled bool
	Winners []address
	won     map[address]bool
	pending map[address]string
}

var (
	quests   []*Quest
	cards    = map[address][]Card{}
	points   = map[address]int64{}
	daily    = map[string]int{}
	projects = map[address]bool{}
	players  []address
	log      []event
	paidOut  int64
	minted   int
)

// receipt is a public case file for every payout or rejection.
type receipt struct {
	N      int
	Quest  int
	Who    address
	Ok     bool
	Check  string
	Paid   int64
	Height int64
	At     int64
}

var receipts []receipt

func addReceipt(q *Quest, who address, ok bool, check string, paid int64) {
	receipts = append(receipts, receipt{len(receipts) + 1, q.ID, who, ok, check, paid, runtime.ChainHeight(), time.Now().Unix()})
	if len(receipts) > 100 {
		receipts = receipts[len(receipts)-100:]
	}
}

type event struct {
	At  int64
	Msg string
}

// ---------- projects ----------

// CreateQuest locks the sent ugnot as the quest pool. Send coins with the tx.
func CreateQuest(cur realm, title, desc, art string, rarity int, kind, arg, pay string, max int, days int) int {
	requireWallet(cur)
	funder := cur.Previous().Address()
	if rarity < Common || rarity > Legendary {
		panic("bad rarity")
	}
	if rarity >= Epic && !projects[funder] && funder != admin {
		panic("only approved projects can create Epic or Legendary quests")
	}
	if r := validKind(kind, arg); r != "" {
		panic(r)
	}
	if pay != PayFixed && pay != PaySplit {
		panic("bad pay style")
	}
	if pay == PaySplit && rarity < Epic && kind != KindPush {
		panic("split pay is for Epic/Legendary or partner quests")
	}
	if max < 1 || (supplyCap[rarity] > 0 && max > supplyCap[rarity]) {
		panic("max winners out of range for this rarity")
	}
	if days < 1 || days > 90 {
		panic("days must be 1-90")
	}
	if strings.TrimSpace(title) == "" || len(title) > 60 || len(desc) > 400 || len(art) > 24 {
		panic("title 1-60, desc up to 400, art key up to 24 chars")
	}
	sent := unsafe.OriginSend().AmountOf("ugnot")
	if sent <= 0 {
		panic("send ugnot to fund the pool")
	}
	q := &Quest{
		ID: len(quests) + 1, Title: title, Desc: desc, Art: art, Funder: funder,
		Rarity: rarity, Kind: kind, Arg: arg, Pay: pay,
		Pool: sent, Funded: sent, Max: max,
		Expires: time.Now().Unix() + int64(days)*daySecs,
		won: map[address]bool{}, pending: map[address]string{},
	}
	if pay == PayFixed {
		if sent%int64(max) != 0 {
			panic("pool must divide evenly by max winners")
		}
		q.Reward = sent / int64(max)
	}
	quests = append(quests, q)
	posted[funder]++
	touch(funder)
	note("quest #" + itoa(q.ID) + " created, pool " + gnot(sent))
	return q.ID
}

// Review approves or rejects a manual proof. Funder or admin only.
func Review(cur realm, id int, wallet address, ok bool) {
	q := mustQuest(id)
	caller := cur.Previous().Address()
	if caller != q.Funder && caller != admin {
		panic("only the quest funder can review")
	}
	if _, has := q.pending[wallet]; !has {
		panic("no pending proof")
	}
	delete(q.pending, wallet)
	if ok {
		award(cur, q, wallet)
	} else {
		addReceipt(q, wallet, false, "project review → rejected", 0)
		note("quest #" + itoa(id) + " proof rejected for " + short(wallet))
	}
}

// Refund returns the unclaimed pool of an expired fixed quest to its funder.
func Refund(cur realm, id int) {
	q := mustQuest(id)
	if q.Pay != PayFixed {
		panic("split quests use Settle")
	}
	if time.Now().Unix() < q.Expires {
		panic("quest still running: pool is locked")
	}
	if q.Pool == 0 {
		panic("nothing to refund")
	}
	amt := q.Pool
	q.Pool = 0
	send(cur, q.Funder, amt)
	note("quest #" + itoa(id) + " refunded " + gnot(amt) + " to funder")
}

// Settle pays a split quest after expiry. Anyone can call it.
func Settle(cur realm, id int) {
	q := mustQuest(id)
	if q.Pay != PaySplit || q.Settled {
		panic("not a split quest or already settled")
	}
	if time.Now().Unix() < q.Expires {
		panic("quest still running")
	}
	q.Settled = true
	n := int64(len(q.Winners))
	if n > 0 {
		share := q.Pool / n
		for _, w := range q.Winners {
			send(cur, w, share)
			q.Pool -= share
			paidOut += share
		}
		note("quest #" + itoa(id) + " split " + gnot(share) + " x " + itoa(int(n)))
	}
	if q.Pool > 0 {
		left := q.Pool
		q.Pool = 0
		send(cur, q.Funder, left)
	}
}

// ---------- questers ----------

// Claim runs the quest's own check on the caller and pays if it passes.
func Claim(cur realm, id int) {
	requireWallet(cur)
	q := mustQuest(id)
	user := cur.Previous().Address()
	if r := verifyReason(q, user); r != "" {
		panic(r)
	}
	award(cur, q, user)
}

// Submit sends a proof (link or text) for a manual quest.
func Submit(cur realm, id int, proof string) {
	requireWallet(cur)
	q := mustQuest(id)
	user := cur.Previous().Address()
	if q.Kind != KindManual {
		panic("not a manual quest")
	}
	open(q, user)
	if len(proof) == 0 || len(proof) > 280 {
		panic("proof must be 1-280 chars")
	}
	touch(user)
	q.pending[user] = proof
	note("quest #" + itoa(id) + " proof submitted by " + short(user))
}

// Complete is called by the partner realm named in a push quest.
func Complete(cur realm, id int, wallet address) {
	q := mustQuest(id)
	if q.Kind != KindPush {
		panic("not a push quest")
	}
	if cur.Previous().PkgPath() != q.Arg {
		panic("only " + q.Arg + " can complete this quest")
	}
	award(cur, q, wallet)
}

// ---------- admin ----------

func ApproveProject(cur realm, p address, on bool) {
	onlyAdmin(cur)
	projects[p] = on
}

// Revoke removes a card from a cheater wallet.
func Revoke(cur realm, wallet address, id int) {
	onlyAdmin(cur)
	list := cards[wallet]
	for i, c := range list {
		if c.QuestID == id {
			cards[wallet] = append(list[:i], list[i+1:]...)
			points[wallet] -= cardPts[c.Rarity]
			note("card from quest #" + itoa(id) + " revoked from " + short(wallet))
			return
		}
	}
	panic("wallet has no card from that quest")
}

// ---------- read-only checks (other realms can call these) ----------

func HasCard(wallet address, id int) bool {
	for _, c := range cards[wallet] {
		if c.QuestID == id {
			return true
		}
	}
	return false
}

func BestRarity(wallet address) int {
	best := 0
	for _, c := range cards[wallet] {
		if c.Rarity > best {
			best = c.Rarity
		}
	}
	return best
}

func HasRarity(wallet address, min int) bool { return BestRarity(wallet) >= min }
func PointsOf(wallet address) int64          { return points[wallet] }
func CardCount(wallet address) int           { return len(cards[wallet]) }

// ---------- internals ----------

func award(cur realm, q *Quest, user address) {
	if r := gateReason(q, user); r != "" {
		panic(r)
	}
	day := strconv.FormatInt(time.Now().Unix()/daySecs, 10)
	key := string(user) + ":" + day
	daily[key]++

	q.won[user] = true
	q.Winners = append(q.Winners, user)
	if _, seen := points[user]; !seen {
		players = append(players, user)
	}
	touch(user)
	if len(cards[user]) == 0 {
		if inv, ok := inviter[user]; ok {
			invitesDone[inv]++
		}
	}
	cards[user] = append(cards[user], Card{
		QuestID: q.ID, Title: q.Title, Art: q.Art, Rarity: q.Rarity,
		Serial: len(q.Winners), Season: Season, At: time.Now().Unix(),
	})
	points[user] += cardPts[q.Rarity]
	minted++

	paid := int64(0)
	if q.Pay == PayFixed {
		paid = q.Reward
	}
	addReceipt(q, user, true, checkLabel(q), paid)
	msg := short(user) + " won " + rarityName[q.Rarity] + " #" + itoa(len(q.Winners)) + " on quest #" + itoa(q.ID)
	if q.Pay == PayFixed {
		q.Pool -= q.Reward
		send(cur, user, q.Reward)
		paidOut += q.Reward
		msg += ", paid " + gnot(q.Reward)
	}
	note(msg)
}

func open(q *Quest, user address) {
	if time.Now().Unix() >= q.Expires {
		panic("quest expired")
	}
	if q.won[user] {
		panic("already claimed: one win per wallet")
	}
}

func send(cur realm, to address, amt int64) {
	if amt <= 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{"ugnot", amt}})
}

// requireWallet blocks calls routed through other realms (anti-farming bots,
// and makes sure sent coins really came from the caller).
func requireWallet(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("call this directly from your wallet")
	}
}

func onlyAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
}

func mustQuest(id int) *Quest {
	if id < 1 || id > len(quests) {
		panic("quest not found")
	}
	return quests[id-1]
}

func note(s string) {
	log = append(log, event{time.Now().Unix(), s})
	if len(log) > 50 {
		log = log[len(log)-50:]
	}
}

func itoa(n int) string { return strconv.Itoa(n) }

func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	f := strings.TrimRight(strconv.FormatInt(frac+1000000, 10)[1:], "0")
	return strconv.FormatInt(whole, 10) + "." + f + " GNOT"
}

func short(a address) string {
	s := string(a)
	if len(s) < 12 {
		return s
	}
	return s[:7] + "…" + s[len(s)-4:]
}

// ---------- pages ----------

func Render(path string) string {
	switch {
	case strings.HasPrefix(path, "api/"):
		return renderAPI(path[4:])
	case path == "":
		return renderBoard()
	case strings.HasPrefix(path, "q/"):
		id, err := strconv.Atoi(path[2:])
		if err != nil || id < 1 || id > len(quests) {
			return "quest not found"
		}
		return renderQuest(quests[id-1])
	case strings.HasPrefix(path, "p/"):
		return renderPassport(address(path[2:]))
	case path == "top":
		return renderTop()
	}
	return "404"
}

func renderBoard() string {
	s := "# MeQuest\n_Quests that verify themselves._ Season " + Season + "\n\n"
	s += "[Leaderboard](:top)\n\n## Quests\n\n"
	if len(quests) == 0 {
		s += "No quests yet.\n"
	}
	for i := len(quests) - 1; i >= 0; i-- {
		q := quests[i]
		s += "- [#" + itoa(q.ID) + " " + q.Title + "](:q/" + itoa(q.ID) + ") · " + rarityName[q.Rarity] +
			" · " + itoa(len(q.Winners)) + "/" + itoa(q.Max) + " claimed · pool " + gnot(q.Pool) + " left\n"
	}
	s += "\n## Live feed\n\n"
	for i := len(log) - 1; i >= 0 && i >= len(log)-10; i-- {
		s += "- " + log[i].Msg + "\n"
	}
	return s
}

func renderQuest(q *Quest) string {
	s := "# #" + itoa(q.ID) + " " + q.Title + "\n\n" + q.Desc + "\n\n"
	s += "- Card: **" + rarityName[q.Rarity] + "** (" + Season + ")\n"
	s += "- Check: " + q.Kind
	if q.Arg != "" {
		s += " `" + q.Arg + "`"
	}
	s += "\n- Pay: " + q.Pay
	if q.Pay == PayFixed {
		s += ", " + gnot(q.Reward) + " per winner"
	}
	s += "\n- Pool: " + gnot(q.Pool) + " locked of " + gnot(q.Funded) + " funded\n"
	s += "- Winners: " + itoa(len(q.Winners)) + "/" + itoa(q.Max) + "\n"
	s += "- Funder: " + short(q.Funder) + "\n- Ends: " + time.Unix(q.Expires, 0).UTC().Format("2006-01-02 15:04 UTC") + "\n"
	return s
}

func renderPassport(w address) string {
	best := BestRarity(w)
	s := "# Passport: " + short(w) + "\n\n**" + rankName[best] + "** · " +
		strconv.FormatInt(points[w], 10) + " pts · " + itoa(len(cards[w])) + " cards\n\n"
	for _, c := range cards[w] {
		s += "- " + rarityName[c.Rarity] + " · " + c.Title + " · #" + itoa(c.Serial) + " · " + c.Season + "\n"
	}
	return s
}

func renderTop() string {
	list := ranked()
	s := "# Season " + Season + " leaderboard\n\n"
	for i, w := range list {
		if i == 10 {
			break
		}
		s += itoa(i+1) + ". [" + short(w) + "](:p/" + string(w) + ") · " + strconv.FormatInt(points[w], 10) + " pts\n"
	}
	return s
}

package rulecalc

import (
	"crypto/sha256"
	"encoding/hex"
	"strings"
)

// App is one grant application. Its ID is its index in the revealed list.
type App struct {
	Title   string
	PkgPath string
	Payout  address
}

// AppsDigest is the commitment to an application list, published before the
// rule phase and checked at reveal: hex(sha256) of one "Title|PkgPath|Payout\n"
// line per app, in order, followed by salt.
// It panics if a field contains "|" or a newline, or the salt contains a
// newline, since the same digest could then open to a different list.
//
// Off-chain equivalent:
//
//	printf 'Title|PkgPath|Payout\n...salt' | sha256sum
func AppsDigest(apps []App, salt string) string {
	if strings.Contains(salt, "\n") {
		panic("rulecalc: salt contains newline")
	}
	var b strings.Builder
	for _, a := range apps {
		fields := []string{a.Title, a.PkgPath, string(a.Payout)}
		for _, f := range fields {
			if strings.ContainsAny(f, "|\n") {
				panic("rulecalc: application field contains | or newline")
			}
		}
		b.WriteString(strings.Join(fields, "|"))
		b.WriteString("\n")
	}
	b.WriteString(salt)
	sum := sha256.Sum256([]byte(b.String()))
	return hex.EncodeToString(sum[:])
}

package rulecalc

import "testing"

func apps2() []App {
	return []App{
		{Title: "Alpha", PkgPath: "gno.land/r/x/alpha", Payout: address("g1alpha")},
		{Title: "Beta", PkgPath: "gno.land/r/x/beta", Payout: address("g1beta")},
	}
}

func TestAppsDigestStable(t *testing.T) {
	a := AppsDigest(apps2(), "salt")
	b := AppsDigest(apps2(), "salt")
	if a != b {
		t.Fatal("same input, different digest")
	}
	if len(a) != 64 {
		t.Fatalf("want 64 hex chars, got %d", len(a))
	}
}

func TestAppsDigestKnownVector(t *testing.T) {
	// sha256("Alpha|gno.land/r/x/alpha|g1alpha\nBeta|gno.land/r/x/beta|g1beta\nsalt")
	// computed independently: printf 'Alpha|...\nBeta|...\nsalt' | sha256sum
	want := "451fc91dfae0103fc7f9a91c168aa15c290f0bbe7217e9acfc900c32ababe09a"
	if got := AppsDigest(apps2(), "salt"); got != want {
		t.Fatalf("digest mismatch: got %s", got)
	}
}

func TestAppsDigestSensitive(t *testing.T) {
	base := AppsDigest(apps2(), "salt")

	swapped := apps2()
	swapped[0], swapped[1] = swapped[1], swapped[0]
	if AppsDigest(swapped, "salt") == base {
		t.Error("order change not detected")
	}

	payout := apps2()
	payout[1].Payout = address("g1other")
	if AppsDigest(payout, "salt") == base {
		t.Error("payout change not detected")
	}

	if AppsDigest(apps2(), "pepper") == base {
		t.Error("salt change not detected")
	}
}

func TestAppsDigestRejectsSeparators(t *testing.T) {
	bad := [][]App{
		{{Title: "A|B", PkgPath: "p", Payout: address("g1")}},
		{{Title: "A", PkgPath: "p\nq", Payout: address("g1")}},
		{{Title: "A", PkgPath: "p", Payout: address("g1|x")}},
	}
	for i, apps := range bad {
		func() {
			defer func() {
				if recover() == nil {
					t.Errorf("case %d: expected panic", i)
				}
			}()
			AppsDigest(apps, "salt")
		}()
	}
}

// A salt holding application lines would let the same digest open to a shorter
// list: [A, B]+salt and [A]+"B|...\nsalt" hash the same bytes.
func TestAppsDigestRejectsSaltHidingApps(t *testing.T) {
	full := AppsDigest(apps2(), "salt")
	defer func() {
		if recover() == nil {
			t.Error("expected panic for a salt with a newline")
		}
	}()
	got := AppsDigest(apps2()[:1], "Beta|gno.land/r/x/beta|g1beta\nsalt")
	if got == full {
		t.Error("the same digest opens to a shorter application list")
	}
}

// Package rulecalc holds the evaluation rule schema for a grant round and the
// deterministic computation of its outcome. It has no state and moves no coins.
package rulecalc

import (
	"errors"
	"strconv"
)

// Method is how evaluator score sheets are aggregated into a winner.
type Method int

const (
	// WeightedSum: the winner has the highest sum of weight*score over all sheets.
	WeightedSum Method = iota + 1
	// MajorityFirst: each sheet's first place is its highest weighted app;
	// the winner has the most first places.
	MajorityFirst
)

// TieBreak decides a top-level tie.
type TieBreak int

const (
	// LowestID: the tied app with the lowest ID wins.
	LowestID TieBreak = iota + 1
	// Refund: no winner; the grant returns to the customer.
	Refund
)

const (
	MinCriteria = 1
	MaxCriteria = 4
	MinWeight   = 1
	MaxWeight   = 10
	MinScore    = 0
	MaxScore    = 10
)

// Criterion is one named, weighted evaluation axis.
type Criterion struct {
	Name   string
	Weight int
}

// Rule is the procedure the evaluators agree on before applications are revealed.
// Rationale is shown to readers and never affects computation.
type Rule struct {
	Method    Method
	Criteria  []Criterion
	Quorum    int
	Tie       TieBreak
	Rationale string
}

// Validate checks the rule against the schema for a round with nEvaluators joined evaluators.
func (r Rule) Validate(nEvaluators int) error {
	if r.Method != WeightedSum && r.Method != MajorityFirst {
		return errors.New("rulecalc: unknown method " + strconv.Itoa(int(r.Method)))
	}
	if r.Tie != LowestID && r.Tie != Refund {
		return errors.New("rulecalc: unknown tie-break " + strconv.Itoa(int(r.Tie)))
	}
	n := len(r.Criteria)
	if n < MinCriteria || n > MaxCriteria {
		return errors.New("rulecalc: need 1-4 criteria, got " + strconv.Itoa(n))
	}
	seen := map[string]bool{}
	for _, c := range r.Criteria {
		if c.Name == "" {
			return errors.New("rulecalc: criterion name is empty")
		}
		if seen[c.Name] {
			return errors.New("rulecalc: duplicate criterion " + c.Name)
		}
		seen[c.Name] = true
		if c.Weight < MinWeight || c.Weight > MaxWeight {
			return errors.New("rulecalc: weight of " + c.Name + " must be 1-10")
		}
	}
	if r.Quorum < 1 || r.Quorum > nEvaluators {
		return errors.New("rulecalc: quorum must be between 1 and " + strconv.Itoa(nEvaluators))
	}
	return nil
}

package rulecalc

import "testing"

func validRule() Rule {
	return Rule{
		Method:   WeightedSum,
		Criteria: []Criterion{{Name: "security", Weight: 3}},
		Quorum:   2,
		Tie:      LowestID,
	}
}

func TestValidateOK(t *testing.T) {
	if err := validRule().Validate(3); err != nil {
		t.Fatalf("valid rule rejected: %v", err)
	}
	r := validRule()
	r.Method = MajorityFirst
	r.Tie = Refund
	r.Criteria = []Criterion{{"a", 1}, {"b", 10}, {"c", 5}, {"d", 2}}
	r.Quorum = 3
	if err := r.Validate(3); err != nil {
		t.Fatalf("valid rule (4 criteria, quorum == evaluators) rejected: %v", err)
	}
}

func TestValidateRejects(t *testing.T) {
	cases := []struct {
		name string
		mod  func(r *Rule)
	}{
		{"no criteria", func(r *Rule) { r.Criteria = nil }},
		{"five criteria", func(r *Rule) {
			r.Criteria = []Criterion{{"a", 1}, {"b", 1}, {"c", 1}, {"d", 1}, {"e", 1}}
		}},
		{"weight 0", func(r *Rule) { r.Criteria = []Criterion{{"a", 0}} }},
		{"weight 11", func(r *Rule) { r.Criteria = []Criterion{{"a", 11}} }},
		{"empty name", func(r *Rule) { r.Criteria = []Criterion{{"", 1}} }},
		{"duplicate name", func(r *Rule) { r.Criteria = []Criterion{{"a", 1}, {"a", 2}} }},
		{"quorum 0", func(r *Rule) { r.Quorum = 0 }},
		{"quorum above evaluators", func(r *Rule) { r.Quorum = 4 }},
		{"unknown method", func(r *Rule) { r.Method = Method(0) }},
		{"unknown method high", func(r *Rule) { r.Method = Method(3) }},
		{"unknown tie", func(r *Rule) { r.Tie = TieBreak(0) }},
		{"unknown tie high", func(r *Rule) { r.Tie = TieBreak(3) }},
	}
	for _, c := range cases {
		r := validRule()
		c.mod(&r)
		if err := r.Validate(3); err == nil {
			t.Errorf("%s: expected error, got nil", c.name)
		}
	}
}

package rulecalc

import (
	"errors"
	"strconv"
)

// Sheet is one evaluator's scores: Scores[app][criterion], apps ordered by ID 0..n-1,
// criteria in the order of Rule.Criteria.
type Sheet struct {
	Evaluator address
	Scores    [][]int
}

// ValidateSheet checks that s scores every app on every criterion within 0-10.
func ValidateSheet(r Rule, nApps int, s Sheet) error {
	if len(s.Scores) != nApps {
		return errors.New("rulecalc: sheet must score " + strconv.Itoa(nApps) + " apps")
	}
	for i, row := range s.Scores {
		if len(row) != len(r.Criteria) {
			return errors.New("rulecalc: app " + strconv.Itoa(i) + " needs " + strconv.Itoa(len(r.Criteria)) + " scores")
		}
		for _, v := range row {
			if v < MinScore || v > MaxScore {
				return errors.New("rulecalc: score out of range 0-10 for app " + strconv.Itoa(i))
			}
		}
	}
	return nil
}

func weighted(r Rule, row []int) int {
	sum := 0
	for c, v := range row {
		sum += r.Criteria[c].Weight * v
	}
	return sum
}

// argmax returns the lowest index holding the maximum and whether that maximum is shared.
func argmax(xs []int) (best int, tied bool) {
	for i := 1; i < len(xs); i++ {
		if xs[i] > xs[best] {
			best = i
			tied = false
		} else if xs[i] == xs[best] {
			tied = true
		}
	}
	return best, tied
}

// Totals returns the per-app figure the rule's method ranks by:
// weighted score sums for WeightedSum, first-place counts for MajorityFirst.
// Sheets must already pass ValidateSheet.
func Totals(r Rule, nApps int, sheets []Sheet) []int {
	tot := make([]int, nApps)
	for _, s := range sheets {
		switch r.Method {
		case WeightedSum:
			for app, row := range s.Scores {
				tot[app] += weighted(r, row)
			}
		case MajorityFirst:
			per := make([]int, nApps)
			for app, row := range s.Scores {
				per[app] = weighted(r, row)
			}
			first, _ := argmax(per) // in-sheet tie -> lowest ID
			tot[first]++
		}
	}
	return tot
}

// Compute returns the winning app ID. paid == false means the grant is refunded:
// no apps, fewer sheets than the quorum, or a top-level tie under the Refund tie-break.
// Sheets must already pass ValidateSheet.
func Compute(r Rule, nApps int, sheets []Sheet) (winner int, paid bool) {
	if nApps < 1 || len(sheets) < r.Quorum {
		return 0, false
	}
	best, tied := argmax(Totals(r, nApps, sheets))
	if tied && r.Tie == Refund {
		return 0, false
	}
	return best, true
}

package rulecalc

import "testing"

// two criteria, weights 3 and 1
func ws(tie TieBreak, quorum int) Rule {
	return Rule{Method: WeightedSum, Criteria: []Criterion{{"a", 3}, {"b", 1}}, Quorum: quorum, Tie: tie}
}

func sheet(ev string, scores ...[]int) Sheet {
	return Sheet{Evaluator: address(ev), Scores: scores}
}

func TestComputeWeightedSum(t *testing.T) {
	// app0: 3*5+1*5=20 and 3*4+1*0=12 -> 32 ; app1: 3*6+1*0=18 and 3*6+1*2=20 -> 38
	sheets := []Sheet{
		sheet("e1", []int{5, 5}, []int{6, 0}),
		sheet("e2", []int{4, 0}, []int{6, 2}),
	}
	w, paid := Compute(ws(LowestID, 2), 2, sheets)
	if !paid || w != 1 {
		t.Fatalf("want winner 1 paid, got %d %v", w, paid)
	}
	tot := Totals(ws(LowestID, 2), 2, sheets)
	if len(tot) != 2 || tot[0] != 32 || tot[1] != 38 {
		t.Fatalf("totals: want [32 38], got %v", tot)
	}
}

func TestComputeMajorityFirst(t *testing.T) {
	r := ws(LowestID, 3)
	r.Method = MajorityFirst
	// sheet firsts: e1 -> 0, e2 -> 1, e3 -> 1. Weighted sums would favor 0 heavily.
	sheets := []Sheet{
		sheet("e1", []int{10, 10}, []int{0, 0}),
		sheet("e2", []int{5, 0}, []int{6, 0}),
		sheet("e3", []int{5, 0}, []int{6, 0}),
	}
	w, paid := Compute(r, 2, sheets)
	if !paid || w != 1 {
		t.Fatalf("want winner 1 paid, got %d %v", w, paid)
	}
	tot := Totals(r, 2, sheets)
	if tot[0] != 1 || tot[1] != 2 {
		t.Fatalf("first-place counts: want [1 2], got %v", tot)
	}
}

func TestComputeMajorityFirstInSheetTieLowestID(t *testing.T) {
	r := ws(LowestID, 1)
	r.Method = MajorityFirst
	// in-sheet tie between app0 and app1 -> first place is app0
	w, paid := Compute(r, 2, []Sheet{sheet("e1", []int{2, 2}, []int{2, 2})})
	if !paid || w != 0 {
		t.Fatalf("want winner 0 paid, got %d %v", w, paid)
	}
}

func TestComputeTieLowestID(t *testing.T) {
	sheets := []Sheet{sheet("e1", []int{2, 0}, []int{1, 3})} // 6 vs 6
	w, paid := Compute(ws(LowestID, 1), 2, sheets)
	if !paid || w != 0 {
		t.Fatalf("want winner 0 paid, got %d %v", w, paid)
	}
}

func TestComputeTieRefund(t *testing.T) {
	sheets := []Sheet{sheet("e1", []int{2, 0}, []int{1, 3})} // 6 vs 6
	_, paid := Compute(ws(Refund, 1), 2, sheets)
	if paid {
		t.Fatal("tie with Refund must not pay")
	}
}

func TestComputeQuorum(t *testing.T) {
	sheets := []Sheet{
		sheet("e1", []int{5, 5}, []int{6, 0}),
		sheet("e2", []int{4, 0}, []int{6, 2}),
	}
	_, paid := Compute(ws(LowestID, 3), 2, sheets)
	if paid {
		t.Fatal("below quorum must not pay")
	}
}

func TestComputeNoSheets(t *testing.T) {
	_, paid := Compute(ws(LowestID, 1), 2, nil)
	if paid {
		t.Fatal("no sheets must not pay")
	}
}

func TestComputeNoApps(t *testing.T) {
	_, paid := Compute(ws(LowestID, 1), 0, []Sheet{sheet("e1")})
	if paid {
		t.Fatal("no apps must not pay")
	}
}

func TestValidateSheet(t *testing.T) {
	r := ws(LowestID, 1)
	if err := ValidateSheet(r, 2, sheet("e1", []int{0, 10}, []int{10, 0})); err != nil {
		t.Fatalf("valid sheet rejected: %v", err)
	}
	bad := []Sheet{
		sheet("e1", []int{11, 0}, []int{0, 0}),           // score 11
		sheet("e1", []int{-1, 0}, []int{0, 0}),           // score -1
		sheet("e1", []int{1, 1}),                         // too few apps
		sheet("e1", []int{1, 1}, []int{1, 1}, []int{1, 1}), // too many apps
		sheet("e1", []int{1}, []int{1, 1}),               // too few criteria
		sheet("e1", []int{1, 1, 1}, []int{1, 1}),         // too many criteria
	}
	for i, s := range bad {
		if err := ValidateSheet(r, 2, s); err == nil {
			t.Errorf("bad sheet %d accepted", i)
		}
	}
}

package mequest

// JSON views for the website, served through Render("api/...").
// Read them with the RPC query vm/qrender, e.g. "<pkgpath>:api/quests".

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/sys/users"
)

func renderAPI(path string) string {
	switch {
	case path == "stats":
		return apiStats()
	case path == "quests":
		out := make([]string, 0, len(quests))
		for _, q := range quests {
			out = append(out, questJSON(q, false))
		}
		return "[" + strings.Join(out, ",") + "]"
	case strings.HasPrefix(path, "q/"):
		id, err := strconv.Atoi(path[2:])
		if err != nil || id < 1 || id > len(quests) {
			return "null"
		}
		return questJSON(quests[id-1], true)
	case strings.HasPrefix(path, "p/"):
		return passportJSON(address(path[2:]))
	case path == "top":
		return topJSON()
	case path == "feed":
		out := []string{}
		for i := len(log) - 1; i >= 0; i-- {
			out = append(out, "{\"at\":"+i64(log[i].At)+",\"msg\":"+js(log[i].Msg)+"}")
		}
		return "[" + strings.Join(out, ",") + "]"
	case path == "receipts":
		out := []string{}
		for i := len(receipts) - 1; i >= 0; i-- {
			r := receipts[i]
			out = append(out, "{\"n\":"+strconv.Itoa(r.N)+",\"quest\":"+strconv.Itoa(r.Quest)+
				",\"title\":"+js(quests[r.Quest-1].Title)+",\"who\":"+who(r.Who)+",\"ok\":"+strconv.FormatBool(r.Ok)+
				",\"check\":"+js(r.Check)+",\"paid\":"+i64(r.Paid)+",\"rarity\":"+strconv.Itoa(quests[r.Quest-1].Rarity)+
				",\"art\":"+js(quests[r.Quest-1].Art)+",\"height\":"+i64(r.Height)+",\"at\":"+i64(r.At)+"}")
		}
		return "[" + strings.Join(out, ",") + "]"
	case path == "projects":
		out := []string{}
		for a, on := range projects {
			if on {
				out = append(out, who(a))
			}
		}
		return "{\"admin\":" + js(string(admin)) + ",\"approved\":[" + strings.Join(out, ",") + "]}"
	}
	return "null"
}

func apiStats() string {
	locked := int64(0)
	open := 0
	now := time.Now().Unix()
	for _, q := range quests {
		locked += q.Pool
		if now < q.Expires && len(q.Winners) < q.Max {
			open++
		}
	}
	return "{\"quests\":" + strconv.Itoa(len(quests)) + ",\"open\":" + strconv.Itoa(open) +
		",\"locked\":" + i64(locked) + ",\"paid\":" + i64(paidOut) +
		",\"cards\":" + strconv.Itoa(minted) + ",\"players\":" + strconv.Itoa(len(players)) + ",\"joined\":" + strconv.Itoa(joined) +
		",\"season\":" + js(Season) + ",\"now\":" + i64(now) + "}"
}

func questJSON(q *Quest, full bool) string {
	s := "{\"id\":" + strconv.Itoa(q.ID) + ",\"title\":" + js(q.Title) + ",\"desc\":" + js(q.Desc) +
		",\"art\":" + js(q.Art) + ",\"funder\":" + who(q.Funder) + ",\"rarity\":" + strconv.Itoa(q.Rarity) +
		",\"kind\":" + js(q.Kind) + ",\"arg\":" + js(q.Arg) + ",\"pay\":" + js(q.Pay) +
		",\"reward\":" + i64(q.Reward) + ",\"pool\":" + i64(q.Pool) + ",\"funded\":" + i64(q.Funded) +
		",\"max\":" + strconv.Itoa(q.Max) + ",\"claimed\":" + strconv.Itoa(len(q.Winners)) +
		",\"pending\":" + strconv.Itoa(len(q.pending)) + ",\"expires\":" + i64(q.Expires) +
		",\"settled\":" + strconv.FormatBool(q.Settled)
	if full {
		w := []string{}
		for i, a := range q.Winners {
			w = append(w, "{\"serial\":"+strconv.Itoa(i+1)+",\"who\":"+who(a)+"}")
		}
		p := []string{}
		for a, proof := range q.pending {
			p = append(p, "{\"who\":"+who(a)+",\"proof\":"+js(proof)+"}")
		}
		s += ",\"winners\":[" + strings.Join(w, ",") + "],\"queue\":[" + strings.Join(p, ",") + "]"
	}
	return s + "}"
}

func passportJSON(a address) string {
	cs := []string{}
	for _, c := range cards[a] {
		cs = append(cs, "{\"quest\":"+strconv.Itoa(c.QuestID)+",\"title\":"+js(c.Title)+",\"art\":"+js(c.Art)+
			",\"rarity\":"+strconv.Itoa(c.Rarity)+",\"serial\":"+strconv.Itoa(c.Serial)+
			",\"season\":"+js(c.Season)+",\"at\":"+i64(c.At)+"}")
	}
	pend := []string{}
	for _, q := range quests {
		if _, ok := q.pending[a]; ok {
			pend = append(pend, strconv.Itoa(q.ID))
		}
	}
	best := BestRarity(a)
	day := strconv.FormatInt(time.Now().Unix()/daySecs, 10)
	return "{\"who\":" + who(a) + ",\"rank\":" + js(rankName[best]) + ",\"best\":" + strconv.Itoa(best) +
		",\"points\":" + i64(points[a]) + ",\"today\":" + strconv.Itoa(daily[string(a)+":"+day]) +
		",\"dailyCap\":" + strconv.Itoa(DailyCap) + ",\"streak\":" + strconv.Itoa(StreakOf(a)) +
		",\"checkedToday\":" + strconv.FormatBool(lastDay[a] == time.Now().Unix()/daySecs && streak[a] > 0) +
		",\"joinRank\":" + strconv.Itoa(joinRank[a]) + ",\"invites\":" + strconv.Itoa(invitesDone[a]) +
		",\"hasInviter\":" + strconv.FormatBool(inviter[a] != "") + ",\"projects\":" + strconv.Itoa(ProjectsDone(a)) +
		",\"posted\":" + strconv.Itoa(posted[a]) + ",\"approved\":" + strconv.FormatBool(projects[a] || a == admin) +
		",\"cards\":[" + strings.Join(cs, ",") + "],\"pending\":[" + strings.Join(pend, ",") + "]}"
}

func topJSON() string {
	list := ranked()
	out := []string{}
	for i, a := range list {
		if i == 50 {
			break
		}
		art := ""
		best := 0
		for _, c := range cards[a] {
			if c.Rarity > best {
				best, art = c.Rarity, c.Art
			}
		}
		out = append(out, "{\"who\":"+who(a)+",\"points\":"+i64(points[a])+",\"best\":"+strconv.Itoa(best)+",\"bestArt\":"+js(art)+
			",\"cards\":"+strconv.Itoa(len(cards[a]))+"}")
	}
	return "[" + strings.Join(out, ",") + "]"
}

func ranked() []address {
	list := make([]address, len(players))
	copy(list, players)
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && points[list[j]] > points[list[j-1]]; j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
	return list
}

// who returns {"addr":..., "name":...}; name is the wallet's unique
// gno.land username from r/sys/users, or "" if it has none.
func who(a address) string {
	name := ""
	if u := users.ResolveAddress(a); u != nil {
		name = u.Name()
	}
	return "{\"addr\":" + js(string(a)) + ",\"name\":" + js(name) + "}"
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

// js quotes a string as a JSON string.
func js(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString("\\\"")
		case r == '\\':
			b.WriteString("\\\\")
		case r == '\n':
			b.WriteString("\\n")
		case r < 0x20:
			h := strconv.FormatInt(int64(r), 16)
			b.WriteString("\\u" + strings.Repeat("0", 4-len(h)) + h)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package mequest

// Self-verifying checks. Every rule here is public code: the board runs it
// on the caller's wallet and only pays when it returns no reason.

import (
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/r/sys/users"
)

const (
	KindCheckin  = "checkin"  // check-in streak of at least Arg days (1 = first check-in)
	KindEarly    = "early"    // among the first Arg wallets to join MeQuest
	KindInvites  = "invites"  // at least Arg invited friends earned a card
	KindProjects = "projects" // cards from at least Arg different projects
	KindCards    = "cards"    // own at least Arg cards
	KindPosted   = "posted"   // funded at least Arg quests as a project
	KindMyRealm  = "myrealm"  // your own realm (gno.land/r/<your addr>/...) calls ProveRealm
	KindGrant    = "grant"    // given by the quest funder (e.g. season top 3)
)

var (
	joinRank    = map[address]int{}
	joined      int
	streak      = map[address]int{}
	lastDay     = map[address]int64{}
	inviter     = map[address]address{}
	invitesDone = map[address]int{}
	posted      = map[address]int{}
)

func validKind(kind, arg string) string {
	switch kind {
	case KindManual, KindPush, KindMyRealm, KindGrant, KindName:
		return ""
	case KindHold:
		if n, err := strconv.ParseInt(arg, 10, 64); err != nil || n < 1 {
			return "hold quests need a ugnot amount as arg"
		}
		return ""
	case KindCard:
		for _, part := range strings.Split(arg, ",") {
			if n, err := strconv.Atoi(strings.TrimSpace(part)); err != nil || n < 1 || n > len(quests) {
				return "card quests need existing quest ids as arg, like 1,2,3"
			}
		}
		return ""
	case KindCheckin, KindEarly, KindInvites, KindProjects, KindCards, KindPosted:
		if n, err := strconv.Atoi(arg); err != nil || n < 1 {
			return "this kind needs a number as arg"
		}
		return ""
	}
	return "bad kind"
}

// verifyReason runs the quest's own check. "" means the wallet passes.
func verifyReason(q *Quest, user address) string {
	n, _ := strconv.Atoi(q.Arg)
	switch q.Kind {
	case KindHold:
		min, _ := strconv.ParseInt(q.Arg, 10, 64)
		if banker.NewReadonlyBanker().GetCoin(user, "ugnot") < min {
			return "check failed: hold at least " + gnot(min)
		}
	case KindName:
		if users.ResolveAddress(user) == nil {
			return "check failed: register a gno.land username first"
		}
	case KindCard:
		for _, part := range strings.Split(q.Arg, ",") {
			id, _ := strconv.Atoi(strings.TrimSpace(part))
			if !HasCard(user, id) {
				return "check failed: you need the card from quest #" + strconv.Itoa(id) + " first"
			}
		}
	case KindCheckin:
		if s := StreakOf(user); s < n {
			return "check failed: check-in streak is " + strconv.Itoa(s) + ", needs " + q.Arg
		}
	case KindEarly:
		r := joinRank[user]
		if r == 0 {
			return "check failed: you haven't joined yet, check in first"
		}
		if r > n {
			return "check failed: you joined as wallet #" + strconv.Itoa(r) + ", only the first " + q.Arg + " get this"
		}
	case KindInvites:
		if invitesDone[user] < n {
			return "check failed: " + strconv.Itoa(invitesDone[user]) + " invited friends earned a card, needs " + q.Arg
		}
	case KindProjects:
		if p := ProjectsDone(user); p < n {
			return "check failed: cards from " + strconv.Itoa(p) + " projects, needs " + q.Arg
		}
	case KindCards:
		if len(cards[user]) < n {
			return "check failed: you own " + strconv.Itoa(len(cards[user])) + " cards, needs " + q.Arg
		}
	case KindPosted:
		if posted[user] < n {
			return "check failed: post a funded quest first"
		}
	case KindManual:
		return "this quest needs a proof: use Submit"
	case KindPush:
		return "finish this quest on the partner app: " + q.Arg
	case KindMyRealm:
		return "deploy your own realm and have it call ProveRealm"
	case KindGrant:
		return "this card is given by the project"
	}
	return ""
}

// gateReason checks board rules shared by every payout.
func gateReason(q *Quest, user address) string {
	if time.Now().Unix() >= q.Expires {
		return "quest expired"
	}
	if q.won[user] {
		return "already claimed: one win per wallet"
	}
	if q.Rarity == Legendary && BestRarity(user) < Epic {
		return "Legendary needs an Epic card first"
	}
	if len(q.Winners) >= q.Max {
		return "all winner slots are taken"
	}
	day := strconv.FormatInt(time.Now().Unix()/daySecs, 10)
	if daily[string(user)+":"+day] >= DailyCap {
		return "daily cap reached: 10 claims per day"
	}
	return ""
}

// CanClaim is a free read-only dry run of Claim: "ok" or the reason it would fail.
func CanClaim(wallet address, id int) string {
	if id < 1 || id > len(quests) {
		return "quest not found"
	}
	q := quests[id-1]
	if r := gateReason(q, wallet); r != "" {
		return r
	}
	if r := verifyReason(q, wallet); r != "" {
		return r
	}
	return "ok"
}

// CheckIn records today's check-in and grows your streak.
func CheckIn(cur realm) int {
	requireWallet(cur)
	user := cur.Previous().Address()
	today := time.Now().Unix() / daySecs
	last, seen := lastDay[user]
	if seen && last == today {
		panic("already checked in today")
	}
	if seen && last == today-1 {
		streak[user]++
	} else {
		streak[user] = 1
	}
	lastDay[user] = today
	touch(user)
	return streak[user]
}

// StreakOf returns the live streak (0 if a day was missed).
func StreakOf(wallet address) int {
	last, seen := lastDay[wallet]
	if !seen || time.Now().Unix()/daySecs-last > 1 {
		return 0
	}
	return streak[wallet]
}

// SetInviter links you to the friend who invited you. Once, before your first card.
func SetInviter(cur realm, friend address) {
	requireWallet(cur)
	user := cur.Previous().Address()
	if friend == user || !friend.IsValid() {
		panic("invalid inviter")
	}
	if _, ok := inviter[user]; ok {
		panic("inviter already set")
	}
	if len(cards[user]) > 0 {
		panic("set your inviter before your first card")
	}
	inviter[user] = friend
	touch(user)
}

// ProveRealm must be called by a realm deployed under the caller's own
// address: gno.land/r/<your g1 address>/anything. That path proves you built it.
func ProveRealm(cur realm, id int) {
	q := mustQuest(id)
	if q.Kind != KindMyRealm {
		panic("not a first-realm quest")
	}
	user := unsafe.OriginCaller()
	prev := cur.Previous()
	if !prev.IsCode() || !strings.HasPrefix(prev.PkgPath(), "gno.land/r/"+string(user)+"/") {
		panic("call this from a realm under gno.land/r/" + string(user) + "/")
	}
	award(cur, q, user)
}

// Grant gives a grant-kind card. Quest funder only (e.g. Season Champion).
func Grant(cur realm, id int, wallet address) {
	q := mustQuest(id)
	if q.Kind != KindGrant {
		panic("not a grant quest")
	}
	if c := cur.Previous().Address(); c != q.Funder && c != admin {
		panic("only the quest funder can grant")
	}
	award(cur, q, wallet)
}

func ProjectsDone(wallet address) int {
	seen := map[address]bool{}
	for _, c := range cards[wallet] {
		seen[quests[c.QuestID-1].Funder] = true
	}
	return len(seen)
}

func JoinRank(wallet address) int  { return joinRank[wallet] }
func InvitesDone(wallet address) int { return invitesDone[wallet] }
func InviterOf(wallet address) address { return inviter[wallet] }

func touch(a address) {
	if joinRank[a] == 0 {
		joined++
		joinRank[a] = joined
	}
}

// checkLabel is the short proof line shown on a receipt.
func checkLabel(q *Quest) string {
	switch q.Kind {
	case KindHold:
		if mustInt64(q.Arg) < 1000 {
			return "holds GNOT → true"
		}
		return "balance >= " + gnot(mustInt64(q.Arg)) + " → true"
	case KindName:
		return "users.ResolveAddress → found"
	case KindCard:
		return "owns cards " + q.Arg + " → true"
	case KindCheckin:
		return "streak >= " + q.Arg + " → true"
	case KindEarly:
		return "join rank <= " + q.Arg + " → true"
	case KindInvites:
		return "invited friends >= " + q.Arg + " → true"
	case KindProjects:
		return "projects done >= " + q.Arg + " → true"
	case KindCards:
		return "cards owned >= " + q.Arg + " → true"
	case KindPosted:
		return "quests posted >= " + q.Arg + " → true"
	case KindManual:
		return "project review → approved"
	case KindPush:
		parts := strings.Split(q.Arg, "/")
		return "reported by the " + parts[len(parts)-1] + " realm"
	case KindMyRealm:
		return "caller realm path → yours"
	case KindGrant:
		return "granted by project"
	}
	return "verified"
}

func mustInt64(s string) int64 {
	n, _ := strconv.ParseInt(s, 10, 64)
	return n
}

// This file is automatically generated and contains metadata about this
// package deployment. It serves as a marker that this package was deployed
// using Gno Studio (or Gno Playground) and may be used by tools for analytics, verification,
